  1	import { randomUUID } from "node:crypto";
  2	
  3	import { Client, type ClientOptions } from "@modelcontextprotocol/sdk/client/index.js";
  4	import { UnauthorizedError } from "@modelcontextprotocol/sdk/client/auth.js";
  5	import type { RequestOptions } from "@modelcontextprotocol/sdk/shared/protocol.js";
  6	import {
  7	  CallToolResultSchema,
  8	  CreateTaskResultSchema,
  9	  type CallToolResult,
 10	  type ClientCapabilities,
 11	  type CompleteRequest,
 12	  type CompleteResult,
 13	  type CreateTaskResult,
 14	  type GetPromptResult,
 15	  type Implementation,
 16	  type ListTasksResult,
 17	  type Prompt,
 18	  type ReadResourceResult,
 19	  type Resource,
 20	  type ResourceTemplate,
 21	  type ServerCapabilities,
 22	  type Task,
 23	  type Tool,
 24	} from "@modelcontextprotocol/sdk/types.js";
 25	import { redactOAuthValue } from "@superfunctions/oauth-core";
 26	
 27	import type {
 28	  McpFnClientState,
 29	  McpFnConfigureClient,
 30	  McpFnDiagnosticEvent,
 31	  McpFnDiagnosticPhase,
 32	  McpFnDiagnosticSink,
 33	  McpFnTarget,
 34	  McpFnTransportHandle,
 35	} from "./types.js";
 36	import { McpFnClientError } from "./types.js";
 37	
 38	export interface McpFnClientOptions {
 39	  target: McpFnTarget;
 40	  info?: Implementation;
 41	  capabilities?: ClientCapabilities;
 42	  clientOptions?: Omit<ClientOptions, "capabilities">;
 43	  configure?: McpFnConfigureClient;
 44	  diagnostics?: McpFnDiagnosticSink;
 45	  requestId?: () => string;
 46	  clock?: () => Date;
 47	  connectRetries?: number;
 48	  connectRetryDelayMs?: number;
 49	}
 50	
 51	export class McpFnClient {
 52	  private readonly options: McpFnClientOptions;
 53	  private readonly listeners = new Set<McpFnDiagnosticSink>();
 54	  private _state: McpFnClientState = "idle";
 55	  private _protocol?: Client;
 56	  private handle?: McpFnTransportHandle;
 57	  private connectPromise?: Promise<void>;
 58	  private closePromise?: Promise<void>;
 59	
 60	  readonly tools = {
 61	    listAll: (options?: RequestOptions) => this.listTools(options),
 62	    call: (name: string, args: Record<string, unknown> = {}, options?: RequestOptions) =>
 63	      this.operation("tools/call", () => this.protocol.callTool(
 64	        { name, arguments: args },
 65	        undefined,
 66	        options,
 67	      ) as Promise<CallToolResult>),
 68	    createTask: (
 69	      name: string,
 70	      args: Record<string, unknown> = {},
 71	      task: { ttl?: number } = {},
 72	      options?: RequestOptions,
 73	    ) => this.operation("tools/call:task", () => this.protocol.request(
 74	      { method: "tools/call", params: { name, arguments: args, task } },
 75	      CreateTaskResultSchema,
 76	      options,
 77	    ) as Promise<CreateTaskResult>),
 78	  };
 79	
 80	  readonly resources = {
 81	    listAll: (options?: RequestOptions) => this.listResources(options),
 82	    listTemplatesAll: (options?: RequestOptions) => this.listResourceTemplates(options),
 83	    read: (uri: string, options?: RequestOptions): Promise<ReadResourceResult> =>
 84	      this.operation("resources/read", () => this.protocol.readResource({ uri }, options)),
 85	    subscribe: async (uri: string, options?: RequestOptions): Promise<void> => {
 86	      await this.operation("resources/subscribe", () =>
 87	        this.protocol.subscribeResource({ uri }, options));
 88	    },
 89	    unsubscribe: async (uri: string, options?: RequestOptions): Promise<void> => {
 90	      await this.operation("resources/unsubscribe", () =>
 91	        this.protocol.unsubscribeResource({ uri }, options));
 92	    },
 93	  };
 94	
 95	  readonly prompts = {
 96	    listAll: (options?: RequestOptions) => this.listPrompts(options),
 97	    get: (
 98	      name: string,
 99	      args?: Record<string, string>,
100	      options?: RequestOptions,
101	    ): Promise<GetPromptResult> => this.operation("prompts/get", () =>
102	      this.protocol.getPrompt({ name, ...(args ? { arguments: args } : {}) }, options)),
103	    complete: (
104	      params: CompleteRequest["params"],
105	      options?: RequestOptions,
106	    ): Promise<CompleteResult> => this.operation("completion/complete", () =>
107	      this.protocol.complete(params, options)),
108	  };
109	
110	  readonly tasks = {
111	    get: (taskId: string, options?: RequestOptions): Promise<Task> =>
112	      this.operation("tasks/get", () =>
113	        this.protocol.experimental.tasks.getTask(taskId, options)),
114	    result: (taskId: string, options?: RequestOptions): Promise<CallToolResult> =>
115	      this.operation("tasks/result", () =>
116	        this.protocol.experimental.tasks.getTaskResult(
117	          taskId,
118	          CallToolResultSchema,
119	          options,
120	        ) as Promise<CallToolResult>),
121	    list: (cursor?: string, options?: RequestOptions): Promise<ListTasksResult> =>
122	      this.operation("tasks/list", () =>
123	        this.protocol.experimental.tasks.listTasks(cursor, options)),
124	    cancel: (taskId: string, options?: RequestOptions): Promise<Task> =>
125	      this.operation("tasks/cancel", () =>
126	        this.protocol.experimental.tasks.cancelTask(taskId, options)),
127	  };
128	
129	  constructor(options: McpFnClientOptions) {
130	    this.options = options;
131	    if ((options.connectRetries ?? 0) < 0) {
132	      throw new Error("McpFn connectRetries must not be negative");
133	    }
134	    if (options.diagnostics) this.listeners.add(options.diagnostics);
135	  }
136	
137	  get state(): McpFnClientState {
138	    return this._state;
139	  }
140	
141	  get protocol(): Client {
142	    if (!this._protocol || this._state !== "connected") {
143	      throw new McpFnClientError(
144	        "MCPFN_CLIENT_NOT_CONNECTED",
145	        "McpFn client is not connected",
146	        { phase: "capability-operation" },
147	      );
148	    }
149	    return this._protocol;
150	  }
151	
152	  getServerCapabilities(): ServerCapabilities | undefined {
153	    return this._protocol?.getServerCapabilities();
154	  }
155	
156	  getServerVersion(): Implementation | undefined {
157	    return this._protocol?.getServerVersion();
158	  }
159	
160	  getTargetDescriptor() {
161	    return this.options.target.describe();
162	  }
163	
164	  onDiagnostic(listener: McpFnDiagnosticSink): () => void {
165	    this.listeners.add(listener);
166	    return () => this.listeners.delete(listener);
167	  }
168	
169	  async connect(): Promise<void> {
170	    if (this._state === "connected") return;
171	    if (this.connectPromise) return this.connectPromise;
172	    if (this._state === "closed") this._state = "idle";
173	    this.connectPromise = this.connectInternal().finally(() => {
174	      this.connectPromise = undefined;
175	    });
176	    return this.connectPromise;
177	  }
178	
179	  private async connectInternal(): Promise<void> {
