110	function boundedFetch(fetchImplementation: typeof fetch, timeoutMs: number): typeof fetch {
111	  if (!Number.isFinite(timeoutMs) || timeoutMs < 1) {
112	    throw new Error("McpFn authorization diagnostic timeoutMs must be positive");
113	  }
114	  return async (input, init = {}) => {
115	    const timeoutSignal = AbortSignal.timeout(timeoutMs);
116	    const signal = init.signal
117	      ? AbortSignal.any([init.signal, timeoutSignal])
118	      : timeoutSignal;
119	    return fetchImplementation(input, { ...init, signal });
120	  };
121	}
