  1	export interface McpFnRedirectPolicy {
  2	  allowDynamicLoopbackPort?: boolean;
  3	  allowLocalhostLoopback?: boolean;
  4	  allowPrivateUseSchemes?: boolean;
  5	}
  6	
  7	export interface McpFnRedirectMatch {
  8	  requested: string;
  9	  registered: string;
 10	  kind: "exact" | "loopback-dynamic-port";
 11	}
 12	
 13	export class McpFnRedirectMismatchError extends Error {
 14	  readonly code = "MCPFN_REDIRECT_MISMATCH";
 15	  readonly requested: string;
 16	
 17	  constructor(requested: string) {
 18	    super("The authorization redirect URI is not registered for this MCP client");
 19	    this.name = "McpFnRedirectMismatchError";
 20	    this.requested = redactRedirect(requested);
 21	  }
 22	}
 23	
 24	/** Exact matching, except an explicitly enabled RFC 8252 loopback port. */
 25	export function matchMcpRedirectUri(
 26	  requested: string | URL,
 27	  registeredRedirectUris: ReadonlyArray<string | URL>,
 28	  policy: McpFnRedirectPolicy = {},
 29	): McpFnRedirectMatch {
 30	  const actual = new URL(requested.toString());
 31	  if (
 32	    !["http:", "https:"].includes(actual.protocol) &&
 33	    policy.allowPrivateUseSchemes !== true
 34	  ) {
 35	    throw new McpFnRedirectMismatchError(actual.toString());
 36	  }
 37	  for (const candidateValue of registeredRedirectUris) {
 38	    const candidate = new URL(candidateValue.toString());
 39	    if (candidate.toString() === actual.toString()) {
 40	      return {
 41	        requested: actual.toString(),
 42	        registered: candidate.toString(),
 43	        kind: "exact",
 44	      };
 45	    }
 46	    if (
 47	      policy.allowDynamicLoopbackPort !== false &&
 48	      isLoopback(actual, policy) &&
 49	      isLoopback(candidate, policy) &&
 50	      candidate.port === "" &&
 51	      actual.port !== "" &&
 52	      equalExceptPort(actual, candidate)
 53	    ) {
 54	      return {
 55	        requested: actual.toString(),
 56	        registered: candidate.toString(),
 57	        kind: "loopback-dynamic-port",
 58	      };
 59	    }
 60	  }
 61	  throw new McpFnRedirectMismatchError(actual.toString());
 62	}
 63	
 64	function isLoopback(url: URL, policy: McpFnRedirectPolicy): boolean {
 65	  if (url.protocol !== "http:") return false;
 66	  const hostname = url.hostname.toLowerCase();
 67	  return hostname === "127.0.0.1" ||
 68	    hostname === "[::1]" ||
 69	    (policy.allowLocalhostLoopback === true && hostname === "localhost");
 70	}
 71	
 72	function equalExceptPort(left: URL, right: URL): boolean {
 73	  return left.protocol === right.protocol &&
 74	    left.hostname.toLowerCase() === right.hostname.toLowerCase() &&
 75	    left.pathname === right.pathname &&
 76	    left.search === right.search &&
 77	    left.hash === right.hash &&
 78	    left.username === right.username &&
 79	    left.password === right.password;
