 78	export function createAuthProviderMcpHandler<TSession extends AuthSession>(
 79	  mcpHandler: McpFnWebStandardHandler,
 80	  options: McpFnAuthProviderAdapterOptions<TSession>,
 81	): (request: Request) => Promise<Response> {
 82	  const adapter = createMcpFnAuthProviderAdapter(options);
 83	  return async (request) => {
 84	    const authenticated = await adapter.authenticate(request.clone());
 85	    if (!authenticated) {
 86	      return Response.json(
 87	        { error: "invalid_token", error_description: "Authentication failed" },
 88	        { status: 401, headers: { "cache-control": "no-store" } },
 89	      );
 90	    }
 91	    const handleOptions: HandleRequestOptions = { authInfo: authenticated.authInfo };
 92	    return mcpHandler(request, handleOptions);
 93	  };
 94	}
