 96	function defaultPrincipal(session: AuthSession): McpFnPrincipal {
 97	  return {
 98	    subject: session.subject.actorId,
 99	    clientId: session.id,
100	    scopes: [...(session.scopes ?? [])],
101	    resourceIds: [...(session.resourceIds ?? [])],
102	    ...(session.expiresAt
103	      ? { expiresAt: Math.floor(session.expiresAt.getTime() / 1_000) }
104	      : {}),
105	    ...(session.subject.tenantId ? { tenantId: session.subject.tenantId } : {}),
106	    ...(session.subject.regionId ? { regionId: session.subject.regionId } : {}),
107	    ...(session.methods ? { authMethods: [...session.methods] } : {}),
108	  };
109	}

