218	export function createMcpAuthorizationCompatibilityHandler(
219	  options: McpFnAuthorizationCompatibilityOptions,
220	): (request: Request) => Promise<Response> {
221	  const issuer = new URL(options.issuer.toString());
222	  issuer.hash = "";
223	  const endpoint = (path: string) => new URL(path, issuer).toString();
224	  const metadata = {
225	    ...options.extraMetadata,
226	    issuer: issuer.toString(),
227	    authorization_endpoint: endpoint("/authorize"),
228	    token_endpoint: endpoint("/token"),
229	    ...(options.clients.register ? { registration_endpoint: endpoint("/register") } : {}),
230	    ...(options.revoke ? { revocation_endpoint: endpoint("/revoke") } : {}),
231	    response_types_supported: ["code"],
232	    grant_types_supported: ["authorization_code", "refresh_token"],
233	    code_challenge_methods_supported: ["S256"],
234	    token_endpoint_auth_methods_supported: ["none", "client_secret_basic", "client_secret_post"],
235	    ...(options.supportedScopes ? { scopes_supported: unique(options.supportedScopes) } : {}),
236	    client_id_metadata_document_supported: options.clientMetadataDocuments?.enabled === true,
237	  };
238	
239	  return async (request): Promise<Response> => {
240	    const url = new URL(request.url);
241	    try {
242	      if (
243	        request.method === "GET" &&
244	        (url.pathname === "/.well-known/oauth-authorization-server" ||
245	          url.pathname === "/.well-known/openid-configuration")
246	      ) {
247	        return json(200, metadata, { "cache-control": "public, max-age=300" });
248	      }
249	      if (request.method === "POST" && url.pathname === "/register") {
250	        if (!options.clients.register) {
251	          throw new McpFnHostedAuthorizationError(
252	            "invalid_request",
253	            "Dynamic client registration is disabled",
254	            { status: 404 },
255	          );
256	        }
257	        const raw = await readBoundedJson(request, 256_000) as OAuthClientMetadata;
258	        const metadata = normalizeClientMetadata(raw);
259	        const registration = await options.clients.register(metadata, request);
260	        await emit(options, "client-registration", "succeeded", undefined, {

item.stdout:
261	          clientId: registration.clientId,
262	          source: registration.source,
263	        });
264	        return json(201, {
265	          ...registration.metadata,
266	          client_id: registration.clientId,
267	        });
268	      }
269	      if (request.method === "GET" && url.pathname === "/authorize") {
270	        const clientId = url.searchParams.get("client_id");
271	        if (!clientId) {
272	          throw new McpFnHostedAuthorizationError("invalid_request", "client_id is required");
273	        }
274	        const client = await resolveClient(options, clientId);
275	        if (!client) {
276	          throw new McpFnHostedAuthorizationError("invalid_client", "Unknown MCP client");
277	        }
278	        const validated = validateMcpAuthorizationRequest({
279	          url,
280	          client,
281	          redirectPolicy: options.redirectPolicy,
282	          allowedResources: options.allowedResources,
283	          supportedScopes: options.supportedScopes,
284	        });
285	        await emit(options, "authorization-request", "succeeded", undefined, {
286	          clientId,
287	          registrationSource: client.source,
288	          redirectMatch: validated.redirectMatch,
289	        });
290	        return options.authorize(validated, request);
291	      }
292	      if (request.method === "POST" && url.pathname === "/token") {
293	        return options.token(request);
294	      }
295	      if (request.method === "POST" && url.pathname === "/revoke" && options.revoke) {
296	        return options.revoke(request);
297	      }
298	      return json(404, { error: "not_found" });
299	    } catch (error) {
300	      const normalized = error instanceof McpFnHostedAuthorizationError
301	        ? error
302	        : new McpFnHostedAuthorizationError(
303	          "server_error",
304	          "MCP authorization compatibility processing failed",
305	          { status: 500 },
306	        );
307	      await emit(options, inferPhase(url.pathname), "failed", normalized.code, {
308	        message: normalized.message,
309	        ...normalized.details,
310	      });
311	      return json(normalized.status, {
312	        error: normalized.code,
313	        error_description: normalized.message,
314	      });
315	    }
316	  };
317	}
