307	      await emit(options, inferPhase(url.pathname), "failed", normalized.code, {
308	        message: normalized.message,
309	        ...normalized.details,
310	      });
311	      return json(normalized.status, {
312	        error: normalized.code,
313	        error_description: normalized.message,
314	      });
315	    }
316	  };
