319	async function resolveClient(
320	  options: McpFnAuthorizationCompatibilityOptions,
321	  clientId: string,
322	): Promise<McpFnNormalizedClientRegistration | null> {
323	  const stored = await options.clients.resolve(clientId);
324	  if (stored) return stored;
325	  if (!options.clientMetadataDocuments?.enabled) return null;
326	  let clientUrl: URL;
327	  try {
328	    clientUrl = new URL(clientId);
329	  } catch {
330	    return null;
331	  }
332	  if (clientUrl.protocol !== "https:" || clientUrl.pathname === "/") return null;
333	  if (!options.clientMetadataDocuments.allow ||
334	      !(await options.clientMetadataDocuments.allow(clientUrl))) {
335	    throw new McpFnHostedAuthorizationError(
336	      "invalid_client",
337	      "Client ID Metadata Document URL is not permitted",
338	    );
339	  }
340	  const fetchImplementation = options.clientMetadataDocuments.fetch ?? globalThis.fetch;
341	  if (!fetchImplementation) throw new Error("A fetch implementation is required");
342	  const response = await fetchImplementation(clientUrl, {
343	    headers: { accept: "application/json" },
344	  });
345	  if (!response.ok) {
346	    await response.body?.cancel();
347	    throw new McpFnHostedAuthorizationError(
348	      "invalid_client",
349	      "Client ID Metadata Document could not be loaded",
350	    );
351	  }
352	  const raw = await readBoundedJson(response, options.clientMetadataDocuments.maxBytes ?? 256_000);
353	  const record = raw as Record<string, unknown>;
354	  if (record.client_id !== undefined && record.client_id !== clientId) {
355	    throw new McpFnHostedAuthorizationError(
356	      "invalid_client_metadata",
357	      "Client ID Metadata Document client_id does not match its URL",
358	    );
359	  }
360	  return normalizeMcpClientRegistration({
361	    clientId,
362	    source: "client-metadata-document",
363	    metadata: normalizeClientMetadata(record as OAuthClientMetadata),
364	  });
365	}
366	
367	function normalizeClientMetadata(value: OAuthClientMetadata): OAuthClientMetadata {
368	  if (!value || typeof value !== "object") {
369	    throw new McpFnHostedAuthorizationError("invalid_client_metadata", "Client metadata must be an object");
370	  }
371	  return {
372	    ...value,
373	    redirect_uris: Array.isArray(value.redirect_uris) ? value.redirect_uris : [],
374	  };
375	}
376	
377	async function readBoundedJson(
378	  source: Request | Response,
379	  maxBytes: number,
380	): Promise<unknown> {
381	  const length = Number(source.headers.get("content-length") ?? "0");
382	  if (Number.isFinite(length) && length > maxBytes) {
383	    throw new McpFnHostedAuthorizationError("invalid_request", "Metadata body is too large", {
384	      status: 413,
385	    });
386	  }
387	  const text = await source.text();
388	  if (new TextEncoder().encode(text).byteLength > maxBytes) {
389	    throw new McpFnHostedAuthorizationError("invalid_request", "Metadata body is too large", {
390	      status: 413,
391	    });
392	  }
393	  try {
394	    return JSON.parse(text);
395	  } catch {
396	    throw new McpFnHostedAuthorizationError("invalid_request", "Metadata body is not valid JSON");
397	  }
398	}
