400	function json(status: number, body: unknown, headers: HeadersInit = {}): Response {
401	  return Response.json(body, {
402	    status,
403	    headers: {
404	      "cache-control": "no-store",
405	      ...Object.fromEntries(new Headers(headers)),
406	    },
407	  });
408	}
409	
410	function unique(values: string[]): string[] {
411	  return [...new Set(values)].sort();
412	}
413	
414	function uniqueUrls(values: Array<string | URL>): string[] {
415	  return unique(values.map((value) => new URL(value.toString()).toString()));
416	}
