418	async function emit(
419	  options: McpFnAuthorizationCompatibilityOptions,
420	  phase: string,
421	  outcome: "succeeded" | "failed",
422	  code?: string,
423	  details?: Record<string, unknown>,
424	): Promise<void> {
425	  await options.diagnostics?.(redactOAuthValue({
426	    phase,
427	    outcome,
428	    ...(code ? { code } : {}),
429	    ...(details ? { details } : {}),
430	  }));
