433	function inferPhase(pathname: string): string {
434	  if (pathname === "/register") return "client-registration";
435	  if (pathname === "/authorize") return "authorization-request";
436	  if (pathname === "/token") return "token-exchange";
437	  if (pathname === "/revoke") return "token-revocation";
438	  return "authorization-server-discovery";
439	}
