 21	export type McpFnOAuthCredentialScope = "all" | "client" | "tokens" | "verifier" | "state";
 22	
 23	export interface McpFnOAuthSessionStore {
 24	  readonly security: "memory" | "encrypted";
 25	  getClientInformation(): Promise<OAuthClientInformationMixed | undefined>;
 26	  setClientInformation(value: OAuthClientInformationMixed): Promise<void>;
 27	  getTokens(): Promise<OAuthTokens | undefined>;
