 36	export class MemoryMcpFnOAuthSessionStore implements McpFnOAuthSessionStore {
 37	  readonly security = "memory" as const;
 38	  private client?: OAuthClientInformationMixed;
 39	  private tokenSet?: OAuthTokens;
 40	  private verifier?: string;
 41	  private pendingState?: string;
 42	
 43	  async getClientInformation(): Promise<OAuthClientInformationMixed | undefined> {
 44	    return this.client ? structuredClone(this.client) : undefined;
 45	  }
