135	export type McpFnOAuthClientPhase =
136	  | "client-registration"
137	  | "authorization-request"
138	  | "authorization-callback"
139	  | "token-exchange"
140	  | "token-refresh"
141	  | "token-revocation";
142	
143	export interface McpFnOAuthClientDiagnostic {
144	  phase: McpFnOAuthClientPhase;
145	  outcome: "started" | "succeeded" | "failed";
146	  code?: string;
147	  at: string;
148	  details?: Record<string, unknown>;
149	}
