166	export class McpFnOAuthClientProvider implements OAuthClientProvider {
167	  readonly redirectUrl: string | URL;
168	  readonly clientMetadata: OAuthClientMetadata;
169	  readonly clientMetadataUrl?: string;
170	  readonly addClientAuthentication?: AddClientAuthentication;
171	  readonly validateResourceURL?: McpFnOAuthClientProviderOptions["validateResourceURL"];
172	  private readonly options: McpFnOAuthClientProviderOptions;
173	  private readonly store: McpFnOAuthSessionStore;
174	
175	  constructor(options: McpFnOAuthClientProviderOptions) {
176	    this.options = options;
177	    this.redirectUrl = options.redirectUrl;
178	    this.clientMetadata = structuredClone(options.clientMetadata);
179	    this.clientMetadataUrl = options.clientMetadataUrl;
180	    this.store = options.store ?? new MemoryMcpFnOAuthSessionStore();
181	    this.addClientAuthentication = options.addClientAuthentication;
182	    this.validateResourceURL = options.validateResourceURL;
183	    if (!this.clientMetadata.redirect_uris?.length) {
184	      throw new Error("McpFn OAuth client metadata requires registered redirect_uris");
185	    }
186	  }
187	
188	  async state(): Promise<string> {
189	    const value = await (this.options.state?.() ?? generateStateId("mcpfn_state"));
190	    await this.store.setState(value);
191	    return value;
192	  }
193	
194	  clientInformation(): Promise<OAuthClientInformationMixed | undefined> {
195	    return this.store.getClientInformation();
196	  }
197	
198	  async saveClientInformation(value: OAuthClientInformationMixed): Promise<void> {
199	    await this.store.setClientInformation(value);
200	    await this.emit("client-registration", "succeeded", undefined, {
201	      clientId: value.client_id,
202	      storage: this.store.security,
203	    });
204	  }
205	
206	  tokens(): Promise<OAuthTokens | undefined> {
207	    return this.store.getTokens();
208	  }
209	
210	  async saveTokens(value: OAuthTokens): Promise<void> {
211	    const previous = await this.store.getTokens();
212	    await this.store.setTokens(value);
213	    await this.emit(previous ? "token-refresh" : "token-exchange", "succeeded", undefined, {
214	      tokenType: value.token_type,
215	      hasRefreshToken: Boolean(value.refresh_token),
216	      storage: this.store.security,
217	    });
218	  }
219	
220	  async redirectToAuthorization(authorizationUrl: URL): Promise<void> {
221	    await this.emit("authorization-request", "started");
222	    const requested = authorizationUrl.searchParams.get("redirect_uri");
223	    if (!requested) {
224	      await this.emit("authorization-request", "failed", "MCPFN_REDIRECT_MISSING");
225	      throw new Error("MCP authorization request is missing redirect_uri");
226	    }
227	    try {
228	      const client = await this.store.getClientInformation();
229	      const registered = "redirect_uris" in (client ?? {}) &&
230	          Array.isArray((client as { redirect_uris?: unknown }).redirect_uris)
231	        ? (client as { redirect_uris: string[] }).redirect_uris
232	        : this.clientMetadata.redirect_uris;
233	      const match = matchMcpRedirectUri(requested, registered, this.options.redirectPolicy);
234	      await this.emit("authorization-request", "succeeded", undefined, {
235	        redirect: match,
236	        clientId: authorizationUrl.searchParams.get("client_id"),
237	      });
238	    } catch (error) {
239	      await this.emit("authorization-request", "failed", readCode(error), {
240	        redirectOrigin: safeOrigin(requested),
241	        message: error instanceof Error ? error.message : String(error),
242	      });
243	      throw error;
244	    }
245	    await this.options.openAuthorization(authorizationUrl);
246	  }
247	
248	  saveCodeVerifier(value: string): Promise<void> {
249	    return this.store.setCodeVerifier(value);
250	  }
251	
252	  async codeVerifier(): Promise<string> {
253	    const value = await this.store.getCodeVerifier();
254	    if (!value) throw new Error("No PKCE verifier is available for this MCP authorization session");
255	    return value;
256	  }
257	
258	  async validateAuthorizationState(value: string | undefined): Promise<void> {
259	    const expected = await this.store.getState();
260	    if (!expected || !value || expected !== value) {
261	      await this.emit("authorization-callback", "failed", "MCPFN_STATE_MISMATCH");
262	      throw new Error("MCP authorization callback state does not match the pending session");
263	    }
264	    await this.store.clear("state");
265	    await this.emit("authorization-callback", "succeeded");
266	  }
267	
268	  invalidateCredentials(scope: McpFnOAuthCredentialScope): Promise<void> {
269	    return this.store.clear(scope);
270	  }
271	
272	  async revoke(): Promise<void> {
273	    const tokens = await this.store.getTokens();
274	    if (!tokens) return;
275	    await this.emit("token-revocation", "started");
276	    try {
277	      await this.options.revoke?.(tokens);
278	      await this.store.clear("tokens");
279	      await this.emit("token-revocation", "succeeded");
280	    } catch (error) {
281	      await this.emit("token-revocation", "failed", readCode(error), {
282	        message: error instanceof Error ? error.message : String(error),
283	      });
284	      throw error;
285	    }
286	  }
287	
288	  private async emit(
289	    phase: McpFnOAuthClientPhase,
290	    outcome: McpFnOAuthClientDiagnostic["outcome"],
291	    code?: string,
292	    details?: Record<string, unknown>,
293	  ): Promise<void> {
294	    await this.options.diagnostics?.(redactOAuthValue({
295	      phase,
296	      outcome,
297	      ...(code ? { code } : {}),
298	      at: (this.options.clock?.() ?? new Date()).toISOString(),
299	      ...(details ? { details } : {}),
300	    }));
301	  }
302	}
303	
304	export function createMcpFnOAuthClientProvider(
305	  options: McpFnOAuthClientProviderOptions,
306	): McpFnOAuthClientProvider {
307	  return new McpFnOAuthClientProvider(options);
308	}
309	
310	function readCode(error: unknown): string | undefined {
311	  if (!error || typeof error !== "object") return undefined;
312	  const value = (error as { code?: unknown }).code;
313	  return typeof value === "string" || typeof value === "number" ? String(value) : undefined;
314	}
315	
316	function safeOrigin(value: string): string {
317	  try {
318	    return new URL(value).origin;
319	  } catch {
320	    return "invalid";
321	  }
322	}

