 94	/** Encrypts client registration, tokens, and the transient verifier at rest. */
 95	export function createEncryptedMcpFnOAuthSessionStore(options: {
 96	  namespace: string;
 97	  keyRef: string;
 98	  cipher: TokenCipher;
 99	  store: McpFnEncryptedSessionRecordStore;
100	}): McpFnOAuthSessionStore {
101	  if (!options.namespace || !options.keyRef) {
102	    throw new Error("Encrypted McpFn OAuth storage requires namespace and keyRef");
103	  }
104	  const key = (part: string) => `${options.namespace}:${part}`;
105	  const get = async <T>(part: string): Promise<T | undefined> => {
106	    const record = await options.store.get(key(part));
107	    if (!record) return undefined;
108	    return JSON.parse(await options.cipher.decrypt(record.ciphertext, record.keyRef)) as T;
109	  };
110	  const put = async (part: string, value: unknown): Promise<void> => {
111	    await options.store.put(key(part), {
112	      ciphertext: await options.cipher.encrypt(JSON.stringify(value), options.keyRef),
113	      keyRef: options.keyRef,
114	    });
115	  };
116	  return {
117	    security: "encrypted",
118	    getClientInformation: () => get("client"),
119	    setClientInformation: (value) => put("client", value),
120	    getTokens: () => get("tokens"),
121	    setTokens: (value) => put("tokens", value),
122	    getCodeVerifier: () => get("verifier"),
123	    setCodeVerifier: (value) => put("verifier", value),
124	    getState: () => get("state"),
125	    setState: (value) => put("state", value),
126	    async clear(scope) {
127	      if (scope === "all" || scope === "client") await options.store.delete(key("client"));
128	      if (scope === "all" || scope === "tokens") await options.store.delete(key("tokens"));
129	      if (scope === "all" || scope === "verifier") await options.store.delete(key("verifier"));
130	      if (scope === "all" || scope === "state") await options.store.delete(key("state"));
131	    },
132	  };
133	}
