152	  redirectUrl: string | URL;
153	  clientMetadata: OAuthClientMetadata;
154	  clientMetadataUrl?: string;
155	  store?: McpFnOAuthSessionStore;
156	  redirectPolicy?: McpFnRedirectPolicy;
157	  openAuthorization(url: URL): void | Promise<void>;
158	  diagnostics?(event: McpFnOAuthClientDiagnostic): void | Promise<void>;
159	  state?: () => string | Promise<string>;
160	  addClientAuthentication?: AddClientAuthentication;
161	  validateResourceURL?(serverUrl: string | URL, resource?: string): Promise<URL | undefined>;
162	  revoke?(tokens: OAuthTokens): void | Promise<void>;
163	  clock?: () => Date;
164	}
