 51	
 52	  constructor(
 53	    code: string,
 54	    message: string,
 55	    options: { status?: number; details?: Record<string, unknown> } = {},
 56	  ) {
 57	    super(message);
 58	    this.name = "McpFnHostedAuthorizationError";
 59	    this.code = code;
 60	    this.status = options.status ?? 400;
 61	    this.details = options.details;
 62	  }
 63	}
