 65	export function normalizeMcpClientRegistration(input: {
 66	  clientId: string;
 67	  source: McpFnClientRegistrationSource;
 68	  metadata: OAuthClientMetadata;
 69	}): McpFnNormalizedClientRegistration {
 70	  if (!input.clientId) {
 71	    throw new McpFnHostedAuthorizationError("invalid_client_metadata", "client_id is required");
 72	  }
 73	  const redirectUris = uniqueUrls(input.metadata.redirect_uris ?? []);
 74	  if (!redirectUris.length) {
 75	    throw new McpFnHostedAuthorizationError(
 76	      "invalid_client_metadata",
 77	      "At least one redirect_uri is required",
 78	    );
 79	  }
 80	  const responseTypes = unique(input.metadata.response_types ?? ["code"]);
 81	  const grantTypes = unique(input.metadata.grant_types ?? ["authorization_code"]);
 82	  return {
 83	    clientId: input.clientId,
 84	    source: input.source,
 85	    redirectUris,
 86	    responseTypes,
 87	    grantTypes,
 88	    tokenEndpointAuthMethod: input.metadata.token_endpoint_auth_method ?? "none",
 89	    metadata: {
 90	      ...input.metadata,
 91	      redirect_uris: redirectUris,
 92	      response_types: responseTypes,
 93	      grant_types: grantTypes,
 94	      token_endpoint_auth_method: input.metadata.token_endpoint_auth_method ?? "none",
 95	    },
 96	  };
