128	  if (!challenge || challenge.scheme.toLowerCase() !== "bearer") {
129	    throw new McpFnAuthAssertionError("Expected a Bearer WWW-Authenticate challenge");
130	  }
131	  const metadataUrl = challenge.parameters.resource_metadata;
132	  if (!metadataUrl) {
133	    throw new McpFnAuthAssertionError(
134	      "Bearer challenge is missing the resource_metadata parameter",
135	    );
136	  }
137	  try {
138	    const parsed = new URL(metadataUrl);
139	    if (!parsed.protocol || !parsed.host) throw new Error("not absolute");
140	  } catch {
141	    throw new McpFnAuthAssertionError(
142	      `Bearer challenge has an invalid resource_metadata URL: ${metadataUrl}`,
143	    );
144	  }
145	  if (expectedMetadataUrl && metadataUrl !== expectedMetadataUrl) {
146	    throw new McpFnAuthAssertionError(
