463	export function assertAuthorizationCodeClientMetadata(
464	  metadata: McpFnOAuthClientMetadata,
465	  expectedClientId?: string,
466	): McpFnOAuthClientMetadata {
467	  if (expectedClientId && metadata.client_id !== new URL(expectedClientId).toString()) {
468	    throw new McpFnAuthAssertionError("OAuth client metadata client_id does not match its document URL");
469	  }
470	  if (!metadata.response_types.includes("code")) {
471	    throw new McpFnAuthAssertionError("OAuth client metadata does not support response_type=code");
