180	async function runOne(
181	  options: McpFnAuthRegressionOptions,
182	  scenario: McpFnAuthProbeScenario,
183	  prepare: () => Promise<McpFnAuthCredential | undefined>,
184	  expected: number | number[],
185	): Promise<McpFnAuthScenarioResult> {
186	  let credential: McpFnAuthCredential | undefined;
187	  try {
188	    credential = await prepare();
189	    const headers = credential
190	      ? new Headers(credential.headers)
191	      : scenario.name === "invalid-credential"
192	        ? invalidHeaders(options)
193	        : new Headers();
194	    const response = await options.target.request(headers, scenario);
195	    expectedStatus(response, expected, scenario.name);
196	    if (
197	      options.kind === "oauth" &&
198	      scenario.name !== "valid-credential"
199	    ) {
200	      assertBearerResourceChallenge(
201	        response,
202	        options.protectedResourceMetadataUrl,
203	      );
204	    }
205	    if (scenario.name === "valid-credential" && credential) {
206	      await options.verifyAuthenticatedResponse?.(response.clone(), credential);
207	    }
208	    return {
209	      name: scenario.name,
210	      status: "passed",
211	      responseStatus: response.status,
212	    };
213	  } catch (error) {
214	    return {
215	      name: scenario.name,
216	      status: "failed",
217	      error: error instanceof Error ? error.message : String(error),
218	    };
219	  } finally {
220	    await credential?.dispose?.();
221	  }
222	}
