 90	function expectedStatus(
 91	  response: Response,
 92	  expected: number | number[],
 93	  name: string,
 94	): void {
 95	  const statuses = Array.isArray(expected) ? expected : [expected];
 96	  if (!statuses.includes(response.status)) {
 97	    throw new McpFnAuthAssertionError(
 98	      `${name} expected HTTP ${statuses.join(" or ")}, received ${response.status}`,
 99	    );
100	  }
101	}
102	
103	export function parseBearerChallenge(
104	  header: string | null,
105	): McpFnBearerChallenge | undefined {
106	  if (!header) return undefined;
107	  const matches = [...header.matchAll(/(?:^|,)\s*([A-Za-z][A-Za-z0-9_-]*)\s+/g)];
108	  const selectedIndex = matches.findIndex((entry) => entry[1].toLowerCase() === "bearer");
109	  if (selectedIndex < 0) return undefined;
110	  const match = matches[selectedIndex];
111	  const start = (match.index ?? 0) + match[0].length;
112	  const end = matches[selectedIndex + 1]?.index ?? header.length;
113	  const parameters: Record<string, string> = {};
114	  const source = header.slice(start, end);
115	  const pattern = /([A-Za-z][A-Za-z0-9_-]*)\s*=\s*(?:"((?:[^"\\]|\\.)*)"|([^,\s]+))/g;
116	  for (const entry of source.matchAll(pattern)) {
117	    const quoted = entry[2]?.replace(/\\(["\\])/g, "$1");
118	    parameters[entry[1]] = quoted ?? entry[3] ?? "";
119	  }
120	  return { scheme: match[1], parameters };
121	}
122	
123	export function assertBearerResourceChallenge(
124	  response: Response,
125	  expectedMetadataUrl?: string,
126	): McpFnBearerChallenge {
127	  const challenge = parseBearerChallenge(response.headers.get("www-authenticate"));
128	  if (!challenge || challenge.scheme.toLowerCase() !== "bearer") {
129	    throw new McpFnAuthAssertionError("Expected a Bearer WWW-Authenticate challenge");
130	  }
131	  const metadataUrl = challenge.parameters.resource_metadata;
132	  if (!metadataUrl) {
133	    throw new McpFnAuthAssertionError(
134	      "Bearer challenge is missing the resource_metadata parameter",
135	    );
136	  }
137	  try {
138	    const parsed = new URL(metadataUrl);
139	    if (!parsed.protocol || !parsed.host) throw new Error("not absolute");
140	  } catch {
141	    throw new McpFnAuthAssertionError(
142	      `Bearer challenge has an invalid resource_metadata URL: ${metadataUrl}`,
143	    );
144	  }
145	  if (expectedMetadataUrl && metadataUrl !== expectedMetadataUrl) {
146	    throw new McpFnAuthAssertionError(
147	      `Expected resource_metadata=${expectedMetadataUrl}, received ${metadataUrl}`,
148	    );
149	  }
150	  return challenge;
151	}
