224	/** Runs the common API-key or OAuth resource-server regression matrix. */
225	export async function runAuthRegressionSuite(
226	  options: McpFnAuthRegressionOptions,
227	): Promise<McpFnAuthScenarioResult[]> {
228	  const issue = (overrides: Partial<McpFnAuthCredentialRequest> = {}) =>
229	    options.provider.issue({
230	      kind: options.kind,
231	      scopes: options.requiredScopes,
232	      resource: options.resource,
233	      ...overrides,
234	    });
235	  const results: McpFnAuthScenarioResult[] = [];
236	  results.push(await runOne(
237	    options,
238	    { name: "missing-credential", kind: options.kind },
239	    async () => undefined,
240	    401,
241	  ));
242	  results.push(await runOne(
243	    options,
244	    { name: "invalid-credential", kind: options.kind },
245	    async () => undefined,
246	    401,
247	  ));
248	  results.push(await runOne(
249	    options,
250	    { name: "valid-credential", kind: options.kind },
251	    () => issue(),
252	    options.expectedAuthenticatedStatuses ?? [200, 201, 202, 204],
253	  ));
254	
255	  const capabilities = options.provider.capabilities ?? {};
256	  if (capabilities.scopes && options.requiredScopes?.length) {
257	    results.push(await runOne(
258	      options,
259	      { name: "insufficient-scope", kind: options.kind },
260	      () => issue({ scopes: [] }),
261	      403,
262	    ));
263	  }
264	  if (capabilities.expiration) {
265	    results.push(await runOne(
266	      options,
267	      { name: "expired-credential", kind: options.kind },
268	      () => issue({ expiresInSeconds: -60 }),
269	      401,
270	    ));
271	  }
272	  if (capabilities.resourceBinding && options.resource) {
273	    results.push(await runOne(
274	      options,
275	      { name: "missing-resource", kind: options.kind },
276	      () => issue({ resource: undefined }),
277	      401,
278	    ));
279	  }
280	  if (capabilities.resourceBinding && options.wrongResource) {
281	    results.push(await runOne(
282	      options,
283	      { name: "wrong-resource", kind: options.kind },
284	      () => issue({ resource: options.wrongResource }),
285	      401,
286	    ));
287	  }
288	  if (capabilities.revocation && options.provider.revoke) {
289	    results.push(await runOne(
290	      options,
291	      { name: "revoked-credential", kind: options.kind },
292	      async () => {
293	        const credential = await issue();
294	        await options.provider.revoke?.(credential);
295	        return credential;
296	      },
297	      401,
298	    ));
299	  }
300	  return results;
301	}
