303	export async function assertAuthRegressionSuite(
304	  options: McpFnAuthRegressionOptions,
305	): Promise<McpFnAuthScenarioResult[]> {
306	  const results = await runAuthRegressionSuite(options);
307	  const failures = results.filter((result) => result.status === "failed");
308	  if (failures.length) {
309	    throw new McpFnAuthAssertionError(
310	      failures.map((failure) => `${failure.name}: ${failure.error}`).join("\n"),
311	    );
312	  }
313	  return results;
314	}
