322	/** Creates a protected MCP initialize probe suitable for local or deployed endpoints. */
323	export function createFetchAuthTarget(
324	  options: McpFnFetchAuthTargetOptions,
325	): McpFnAuthTarget {
326	  const fetchImplementation = options.fetch ?? globalThis.fetch;
327	  if (!fetchImplementation) {
328	    throw new Error("A fetch implementation is required");
329	  }
330	  return {
331	    async request(authHeaders, scenario) {
332	      const configured = typeof options.requestInit === "function"
333	        ? options.requestInit(scenario)
334	        : options.requestInit ?? {};
335	      const headers = new Headers(configured.headers);
336	      headers.set("accept", "application/json, text/event-stream");
337	      headers.set("content-type", "application/json");
338	      authHeaders.forEach((value, name) => headers.set(name, value));
339	      return fetchImplementation(options.url, {
340	        method: "POST",
341	        body: JSON.stringify({
342	          jsonrpc: "2.0",
