  1	import type { CallToolResult } from "@modelcontextprotocol/sdk/types.js";
  2	
  3	import { McpFnAssertionError, assertStructuredTextParity, stableJson } from "./assertions.js";
  4	import type { McpFnTestClient } from "./client.js";
  5	
  6	export interface McpFnToolScenario {
  7	  name: string;
  8	  kind?: "tools.call";
  9	  tool: string;
 10	  arguments?: Record<string, unknown>;
 11	  expect?: {
 12	    isError?: boolean;
 13	    structuredContent?: unknown;
 14	    structuredTextParity?: boolean;
 15	  };
 16	  verify?(result: CallToolResult): void | Promise<void>;
 17	}
 18	
 19	export interface McpFnInventoryScenario {
 20	  name: string;
 21	  kind: "tools.list" | "resources.list" | "resources.templates.list" | "prompts.list";
 22	  expectNames?: string[];
 23	}
 24	
 25	export interface McpFnResourceScenario {
 26	  name: string;
 27	  kind: "resources.read" | "resources.subscribe" | "resources.unsubscribe";
 28	  uri: string;
 29	  expect?: unknown;
 30	}
 31	
 32	export interface McpFnPromptScenario {
 33	  name: string;
 34	  kind: "prompts.get";
 35	  prompt: string;
 36	  arguments?: Record<string, string>;
 37	  expect?: unknown;
 38	}
 39	
 40	export interface McpFnInitializeScenario {
 41	  name: string;
 42	  kind: "initialize";
 43	  expectCapabilities?: Record<string, unknown>;
 44	}
 45	
 46	export type McpFnScenario =
 47	  | McpFnToolScenario
 48	  | McpFnInventoryScenario
 49	  | McpFnResourceScenario
 50	  | McpFnPromptScenario
 51	  | McpFnInitializeScenario;
 52	
 53	export interface McpFnScenarioResult {
 54	  name: string;
 55	  operation: string;
 56	  tool?: string;
 57	  status: "passed" | "failed";
 58	  durationMs: number;
 59	  error?: string;
 60	}
 61	
 62	export async function runScenarios(
 63	  client: McpFnTestClient<unknown>,
 64	  scenarios: McpFnScenario[],
 65	): Promise<McpFnScenarioResult[]> {
 66	  const results: McpFnScenarioResult[] = [];
 67	  for (const scenario of scenarios) {
 68	    const startedAt = performance.now();
 69	    const operation = scenario.kind ?? "tools.call";
 70	    try {
 71	      await executeScenario(client, scenario);
 72	      results.push({
 73	        name: scenario.name,
 74	        operation,
 75	        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
 76	        status: "passed",
 77	        durationMs: performance.now() - startedAt,
 78	      });
 79	    } catch (error) {
 80	      results.push({
 81	        name: scenario.name,
 82	        operation,
 83	        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
 84	        status: "failed",
 85	        durationMs: performance.now() - startedAt,
 86	        error: error instanceof Error ? error.message : String(error),
 87	      });
 88	    }
 89	  }
 90	  return results;
 91	}
 92	
 93	async function executeScenario(
 94	  client: McpFnTestClient<unknown>,
 95	  scenario: McpFnScenario,
 96	): Promise<void> {
 97	  const kind = scenario.kind ?? "tools.call";
 98	  if (kind === "tools.call" && isToolScenario(scenario)) {
 99	    const result = await client.callTool(scenario.tool, scenario.arguments);
100	    if (result.isError && scenario.expect?.isError === undefined) {
101	      throw new McpFnAssertionError(
102	        "Tool returned isError=true without an explicit expect.isError=true assertion",
103	      );
104	    }
105	    if (
106	      scenario.expect?.isError !== undefined &&
107	      Boolean(result.isError) !== scenario.expect.isError
108	    ) {
109	      throw new McpFnAssertionError(
110	        `Expected isError=${scenario.expect.isError}, received ${Boolean(result.isError)}`,
111	      );
112	    }
113	    if (
114	      scenario.expect &&
115	      Object.prototype.hasOwnProperty.call(scenario.expect, "structuredContent") &&
116	      stableJson(result.structuredContent) !== stableJson(scenario.expect.structuredContent)
117	    ) {
118	      throw new McpFnAssertionError(
119	        `Structured result mismatch\nexpected: ${stableJson(scenario.expect.structuredContent)}\nactual:   ${stableJson(result.structuredContent)}`,
120	      );
121	    }
122	    if (scenario.expect?.structuredTextParity) assertStructuredTextParity(result);
123	    await scenario.verify?.(result);
124	    return;
125	  }
126	  if (kind === "initialize" && scenario.kind === "initialize") {
127	    const actual = client.client.getServerCapabilities() ?? {};
128	    if (scenario.expectCapabilities && stableJson(actual) !== stableJson(scenario.expectCapabilities)) {
129	      throw new McpFnAssertionError(
130	        `Capability mismatch\nexpected: ${stableJson(scenario.expectCapabilities)}\nactual:   ${stableJson(actual)}`,
131	      );
132	    }
133	    return;
134	  }
135	  if (isInventoryScenario(scenario)) {
136	    const values = kind === "tools.list"
137	      ? await client.listTools()
138	      : kind === "resources.list"
139	        ? await client.listResources()
140	        : kind === "resources.templates.list"
141	          ? await client.listResourceTemplates()
142	          : await client.listPrompts();
143	    if (scenario.expectNames) {
144	      const actual = values.map((value) => value.name).sort();
145	      const expected = [...scenario.expectNames].sort();
146	      if (stableJson(actual) !== stableJson(expected)) {
147	        throw new McpFnAssertionError(
148	          `Inventory mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
149	        );
150	      }
151	    }
152	    return;
153	  }
154	  if (scenario.kind === "resources.read") {
155	    assertExpected(await client.readResource(scenario.uri), scenario.expect);
156	    return;
157	  }
158	  if (scenario.kind === "resources.subscribe") {
159	    await client.subscribeResource(scenario.uri);
160	    return;
161	  }
162	  if (scenario.kind === "resources.unsubscribe") {
163	    await client.unsubscribeResource(scenario.uri);
164	    return;
165	  }
166	  if (scenario.kind === "prompts.get") {
167	    assertExpected(
168	      await client.getPrompt(scenario.prompt, scenario.arguments),
169	      scenario.expect,
170	    );
171	    return;
172	  }
173	  throw new McpFnAssertionError(`Unsupported scenario operation ${kind}`);
174	}
175	
176	function assertExpected(actual: unknown, expected: unknown): void {
177	  if (expected !== undefined && stableJson(actual) !== stableJson(expected)) {
178	    throw new McpFnAssertionError(
179	      `Scenario result mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
180	    );
181	  }
182	}
183	
184	function isToolScenario(scenario: McpFnScenario): scenario is McpFnToolScenario {
185	  return "tool" in scenario;
186	}
187	
188	function isInventoryScenario(scenario: McpFnScenario): scenario is McpFnInventoryScenario {
189	  return ["tools.list", "resources.list", "resources.templates.list", "prompts.list"]
190	    .includes(scenario.kind ?? "");
191	}
