  3	import type { McpFnManifest } from "@mcpfn/core";
  4	
  5	import { assertManifestContract } from "./assertions.js";
  6	import { McpFnTestClient, type McpFnTestClientOptions } from "./client.js";
  7	import {
  8	  runScenarios,
  9	  type McpFnScenario,
 10	  type McpFnScenarioResult,
 11	} from "./scenarios.js";
 12	
 13	export interface RunMcpFnTargetSuiteOptions {
 14	  target: McpFnTarget;
 15	  scenarios?: McpFnScenario[];
 16	  manifest?: McpFnManifest;
 17	  expectedToolNames?: readonly string[];
 18	  clientInfo?: Implementation;
 19	  client?: McpFnTestClientOptions;
 20	}
 21	
 22	export interface McpFnTargetSuiteReport {
 23	  ok: boolean;
 24	  target: McpFnTargetDescriptor;
 25	  server?: Implementation;
 26	  capabilities?: ServerCapabilities;
 27	  manifestChecked: boolean;
 28	  total: number;
 29	  passed: number;
 30	  failed: number;
 31	  results: McpFnScenarioResult[];
 32	}
 33	
 34	/** Runs local, stdio, HTTP, or custom targets through the production session engine. */
 35	export async function runMcpFnTargetSuite(
 36	  options: RunMcpFnTargetSuiteOptions,
 37	): Promise<McpFnTargetSuiteReport> {
 38	  const client = await McpFnTestClient.connectTarget(
 39	    options.target,
 40	    options.clientInfo ?? { name: "mcpfn-suite", version: "0.0.1" },
 41	    options.client,
 42	  );
 43	  try {
 44	    if (options.manifest) {
 45	      await assertManifestContract(client, options.manifest, {
 46	        expectedToolNames: options.expectedToolNames,
 47	      });
 48	    }
 49	    const results = await runScenarios(client, options.scenarios ?? []);
 50	    const failed = results.filter((result) => result.status === "failed").length;
 51	    return {
 52	      ok: failed === 0,
 53	      target: options.target.describe(),
 54	      server: client.session.getServerVersion(),
 55	      capabilities: client.session.getServerCapabilities(),
 56	      manifestChecked: Boolean(options.manifest),
 57	      total: results.length,
 58	      passed: results.length - failed,
 59	      failed,
 60	      results,
 61	    };
 62	  } finally {
 63	    await client.close();
 64	  }
 65	}

