111	      );
112	    }
113	    if (
114	      scenario.expect &&
115	      Object.prototype.hasOwnProperty.call(scenario.expect, "structuredContent") &&
116	      stableJson(result.structuredContent) !== stableJson(scenario.expect.structuredContent)
117	    ) {
118	      throw new McpFnAssertionError(
119	        `Structured result mismatch\nexpected: ${stableJson(scenario.expect.structuredContent)}\nactual:   ${stableJson(result.structuredContent)}`,
120	      );
121	    }
122	    if (scenario.expect?.structuredTextParity) assertStructuredTextParity(result);
123	    await scenario.verify?.(result);
124	    return;
125	  }
126	  if (kind === "initialize" && scenario.kind === "initialize") {
127	    const actual = client.client.getServerCapabilities() ?? {};
128	    if (scenario.expectCapabilities && stableJson(actual) !== stableJson(scenario.expectCapabilities)) {
129	      throw new McpFnAssertionError(
130	        `Capability mismatch\nexpected: ${stableJson(scenario.expectCapabilities)}\nactual:   ${stableJson(actual)}`,
131	      );
132	    }
133	    return;
134	  }
135	  if (isInventoryScenario(scenario)) {
136	    const values = kind === "tools.list"
137	      ? await client.listTools()
138	      : kind === "resources.list"
139	        ? await client.listResources()
140	        : kind === "resources.templates.list"
141	          ? await client.listResourceTemplates()
142	          : await client.listPrompts();
143	    if (scenario.expectNames) {
144	      const actual = values.map((value) => value.name).sort();
145	      const expected = [...scenario.expectNames].sort();
146	      if (stableJson(actual) !== stableJson(expected)) {
147	        throw new McpFnAssertionError(
148	          `Inventory mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
149	        );
150	      }
151	    }
152	    return;
153	  }
154	  if (scenario.kind === "resources.read") {
155	    assertExpected(await client.readResource(scenario.uri), scenario.expect);
156	    return;
157	  }
158	  if (scenario.kind === "resources.subscribe") {
159	    await client.subscribeResource(scenario.uri);
160	    return;
161	  }
162	  if (scenario.kind === "resources.unsubscribe") {
163	    await client.unsubscribeResource(scenario.uri);
164	    return;
165	  }
166	  if (scenario.kind === "prompts.get") {
167	    assertExpected(
168	      await client.getPrompt(scenario.prompt, scenario.arguments),
169	      scenario.expect,
170	    );
171	    return;
172	  }
173	  throw new McpFnAssertionError(`Unsupported scenario operation ${kind}`);
174	}
175	
176	function assertExpected(actual: unknown, expected: unknown): void {
177	  if (expected !== undefined && stableJson(actual) !== stableJson(expected)) {
178	    throw new McpFnAssertionError(
179	      `Scenario result mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
180	    );
181	  }
182	}
183	
184	function isToolScenario(scenario: McpFnScenario): scenario is McpFnToolScenario {
185	  return "tool" in scenario;
186	}
187	
188	function isInventoryScenario(scenario: McpFnScenario): scenario is McpFnInventoryScenario {
189	  return ["tools.list", "resources.list", "resources.templates.list", "prompts.list"]
190	    .includes(scenario.kind ?? "");
191	}
  1	import type { Implementation, ServerCapabilities } from "@modelcontextprotocol/sdk/types.js";
  2	import type { McpFnTarget, McpFnTargetDescriptor } from "@mcpfn/client";
  3	import type { McpFnManifest } from "@mcpfn/core";
  4	
