  2	import path from "node:path";
  3	import { cac } from "cac";
  4	import { diagnoseMcpAuthorization } from "@mcpfn/auth";
  5	import {
  6	  stdioTarget,
  7	  streamableHttpTarget,
  8	  type McpFnTarget,
  9	} from "@mcpfn/client";
 10	import {
 11	  diffManifests,
 12	  validateManifest,
 13	  type McpFnManifest,
 14	} from "@mcpfn/core";
 15	import { McpFnInspector } from "@mcpfn/inspector";
 16	import {
 17	  McpFnTestClient,
 18	  McpFnAssertionError,
 19	  assertManifestContract,
 20	  runOfficialConformance,
 21	  runMcpFnTargetSuite,
