 24	
 25	import { loadManifestSource, loadScenarios } from "./load.js";
 26	
 27	export { loadManifestSource, loadScenarios };
 28	
 29	export interface CliRunOptions {
 30	  cwd?: string;
 31	  stdout?: (text: string) => void;
 32	  stderr?: (text: string) => void;
 33	}
 34	
 35	export async function runCli(
 36	  argv = process.argv.slice(2),
 37	  runOptions: CliRunOptions = {},
 38	): Promise<number> {
 39	  const cwd = runOptions.cwd ?? process.cwd();
 40	  const stdout = runOptions.stdout ?? ((text: string) => process.stdout.write(text));
 41	  const stderr = runOptions.stderr ?? ((text: string) => process.stderr.write(text));
 42	  let exitCode = 0;
 43	  const cli = cac("mcpfn");
 44	
 45	  cli.command("manifest <source>", "Generate a canonical manifest from a server or registry module")
 46	    .option("--output <path>", "Write the manifest to a file")
 47	    .option("--name <name>", "Server name when source exports a registry")
 48	    .option("--version <version>", "Server version when source exports a registry")
 49	    .action(async (source: string, options: { output?: string; name?: string; version?: string }) => {
 50	      const info = options.name && options.version
 51	        ? { name: options.name, version: options.version }
 52	        : undefined;
 53	      const { manifest } = await loadManifestSource(source, cwd, info);
 54	      const serialized = `${JSON.stringify(manifest, null, 2)}\n`;
 55	      if (options.output) {
 56	        const outputPath = path.resolve(cwd, options.output);
 57	        await writeFile(outputPath, serialized, "utf8");
 58	        stdout(`Wrote ${outputPath}\n`);
 59	      } else {
 60	        stdout(serialized);
 61	      }
 62	    });
 63	
 64	  cli.command("validate <manifest>", "Validate a canonical McpFn manifest and its hash")
 65	    .action(async (manifestPath: string) => {
 66	      const parsed = JSON.parse(await readFile(path.resolve(cwd, manifestPath), "utf8"));
 67	      const manifest = validateManifest(parsed);
 68	      stdout(`Valid McpFn manifest ${manifest.server.name}@${manifest.server.version} (${manifest.hash})\n`);
 69	    });
 70	
 71	  cli.command("diff <before> <after>", "Classify MCP contract changes")
 72	    .option("--json", "Print machine-readable JSON")
 73	    .option("--fail-on-behavioral", "Fail when descriptions, titles, or annotations change")
 74	    .action(async (
 75	      beforePath: string,
 76	      afterPath: string,
 77	      options: { json?: boolean; failOnBehavioral?: boolean },
 78	    ) => {
 79	      const read = async (file: string): Promise<McpFnManifest> =>
 80	        validateManifest(JSON.parse(await readFile(path.resolve(cwd, file), "utf8")));
 81	      const result = diffManifests(await read(beforePath), await read(afterPath));
 82	      if (options.json) {
 83	        stdout(`${JSON.stringify(result, null, 2)}\n`);
 84	      } else {
 85	        stdout(`breaking=${result.summary.breaking} additive=${result.summary.additive} behavioral=${result.summary.behavioral}\n`);
 86	        for (const change of result.changes) {
 87	          stdout(`${change.severity.toUpperCase()} ${change.code} ${change.path}: ${change.message}\n`);
 88	        }
 89	      }
 90	      if (!result.compatible || (options.failOnBehavioral && result.summary.behavioral > 0)) {
 91	        exitCode = 1;
 92	      }
 93	    });
 94	
 95	  cli.command("test <server> <scenarios>", "Run protocol-level semantic regression scenarios")
 96	    .option("--output <path>", "Write a JSON report")
 97	    .option(
 98	      "--visible-tools <names>",
 99	      "Comma-separated tool names expected for a request-filtered server",
100	    )
101	    .action(async (
102	      serverPath: string,
103	      scenariosPath: string,
104	      options: { output?: string; visibleTools?: string },
105	    ) => {
106	      const loaded = await loadManifestSource(serverPath, cwd);
107	      if (!loaded.server) {
108	        throw new Error("The test command requires a module exporting McpFnServer");
109	      }
110	      const client = await McpFnTestClient.connect(loaded.server);
111	      try {
112	        await assertManifestContract(client, loaded.manifest, {
113	          expectedToolNames: options.visibleTools
114	            ?.split(",")
115	            .map((name) => name.trim())
116	            .filter(Boolean),
117	        });
118	        const results = await runScenarios(client, await loadScenarios(scenariosPath, cwd));
119	        const report = {
120	          manifestHash: loaded.manifest.hash,
121	          total: results.length,
122	          passed: results.filter((result) => result.status === "passed").length,
123	          failed: results.filter((result) => result.status === "failed").length,
124	          results,
125	        };
126	        const serialized = `${JSON.stringify(report, null, 2)}\n`;
127	        if (options.output) {
128	          await writeFile(path.resolve(cwd, options.output), serialized, "utf8");
129	        }
130	        stdout(serialized);
131	        if (report.failed > 0) exitCode = 1;
132	      } finally {
133	        await client.close();
134	      }
135	    });
136	
137	  cli.command("conformance <url>", "Run the official MCP conformance package against a server")
138	    .option("--suite <suite>", "active, all, or pending")
139	    .option("--scenario <scenario>", "Run one official scenario")
140	    .option("--expected-failures <path>", "Expected-failures baseline")
141	    .option("--output-dir <path>", "Directory for official conformance artifacts")
142	    .option("--spec-version <version>", "MCP specification version")
143	    .option("--verbose", "Show official runner diagnostics")
144	    .action(async (url: string, options: {
145	      suite?: "active" | "all" | "pending";
146	      scenario?: string;
147	      expectedFailures?: string;
148	      outputDir?: string;
149	      specVersion?: string;
150	      verbose?: boolean;
151	    }) => {
152	      const result = await runOfficialConformance({
153	        url,
154	        suite: options.suite,
155	        scenario: options.scenario,
156	        expectedFailures: options.expectedFailures
157	          ? path.resolve(cwd, options.expectedFailures)
158	          : undefined,
159	        outputDir: options.outputDir ? path.resolve(cwd, options.outputDir) : undefined,
160	        specVersion: options.specVersion,
161	        verbose: options.verbose,
162	        cwd,
163	        stdio: "pipe",
164	      });
165	      if (result.stdout) stdout(result.stdout);
166	      if (result.stderr) stderr(result.stderr);
167	      exitCode = result.exitCode;
168	    });
169	
170	  cli.command("inspect <target>", "Inventory an HTTP or stdio MCP target")
171	    .option("--stdio", "Treat target as an executable instead of an HTTP URL")
172	    .option("--args <json>", "JSON array of stdio executable arguments")
173	    .option("--output <path>", "Write the redacted JSON snapshot")
174	    .action(async (targetValue: string, options: {
175	      stdio?: boolean;
176	      args?: string;
177	      output?: string;
178	    }) => {
179	      const target = parseTarget(targetValue, options, cwd);
180	      const inspector = McpFnInspector.create({ target });
181	      await inspector.connect();
182	      try {
183	        const serialized = `${JSON.stringify(await inspector.snapshot(), null, 2)}\n`;
184	        if (options.output) {
185	          await writeFile(path.resolve(cwd, options.output), serialized, "utf8");
186	        }
187	        stdout(serialized);
188	      } finally {
189	        await inspector.close();
190	      }
191	    });
192	
193	  cli.command("test-target <target> <scenarios>", "Run scenarios against an HTTP or stdio MCP target")
194	    .option("--stdio", "Treat target as an executable instead of an HTTP URL")
195	    .option("--args <json>", "JSON array of stdio executable arguments")
196	    .option("--output <path>", "Write the JSON report")
197	    .action(async (targetValue: string, scenariosPath: string, options: {
198	      stdio?: boolean;
199	      args?: string;
200	      output?: string;
201	    }) => {
202	      const report = await runMcpFnTargetSuite({
203	        target: parseTarget(targetValue, options, cwd),
204	        scenarios: await loadScenarios(scenariosPath, cwd),
205	      });
206	      const serialized = `${JSON.stringify(report, null, 2)}\n`;
207	      if (options.output) {
208	        await writeFile(path.resolve(cwd, options.output), serialized, "utf8");
209	      }
210	      stdout(serialized);
211	      if (!report.ok) exitCode = 1;
212	    });
213	
214	  cli.command("auth-diagnose <url>", "Probe OAuth discovery without opening a browser")
215	    .option("--timeout <milliseconds>", "Per-request timeout in milliseconds")
216	    .option("--output <path>", "Write the redacted JSON report")
217	    .action(async (url: string, options: { timeout?: string; output?: string }) => {
218	      const timeoutMs = options.timeout === undefined
219	        ? undefined
220	        : Number.parseInt(options.timeout, 10);
221	      if (timeoutMs !== undefined && (!Number.isFinite(timeoutMs) || timeoutMs < 1)) {
222	        throw new Error("--timeout must be a positive integer");
223	      }
224	      const report = await diagnoseMcpAuthorization(url, { timeoutMs });
225	      const serialized = `${JSON.stringify(report, null, 2)}\n`;
226	      if (options.output) {
227	        await writeFile(path.resolve(cwd, options.output), serialized, "utf8");
228	      }
229	      stdout(serialized);
230	      if (!report.ok) exitCode = 1;
231	    });
232	
233	  cli.help();
234	  cli.version("0.0.1");
235	  try {
236	    const parsed = cli.parse(["node", "mcpfn", ...argv], { run: false });
237	    if (!cli.matchedCommand) {
238	      if (parsed.options.help || parsed.options.version) return 0;
239	      stderr(argv.length ? `Unknown command: ${argv[0]}\n` : "A command is required\n");
240	      return 2;
241	    }
242	    await cli.runMatchedCommand();
243	  } catch (error) {
244	    stderr(`${error instanceof Error ? error.message : String(error)}\n`);
245	    if (error instanceof McpFnAssertionError) return 1;
246	    return 2;
247	  }
248	  return exitCode;
249	}
250	
251	function parseTarget(
252	  targetValue: string,
253	  options: { stdio?: boolean; args?: string },
254	  cwd: string,
255	): McpFnTarget {
256	  if (!options.stdio) {
257	    if (options.args) throw new Error("--args requires --stdio");
258	    return streamableHttpTarget(targetValue);
259	  }
260	  let args: string[] | undefined;
