 19	
 20	export interface McpFnInspectorSnapshot {
 21	  target: McpFnTargetDescriptor;
 22	  state: string;
 23	  server?: Implementation;
 24	  capabilities?: ServerCapabilities;
 25	  tools: Tool[];
