 32	export type McpFnInspectorOperation =
 33	  | { kind: "tools.call"; name: string; arguments?: Record<string, unknown> }
 34	  | { kind: "resources.read"; uri: string }
 35	  | { kind: "prompts.get"; name: string; arguments?: Record<string, string> };
 36	
 37	export type McpFnInspectorOperationResult =
 38	  | CallToolResult
 39	  | ReadResourceResult
 40	  | GetPromptResult;
 41	
 42	export interface McpFnExportedScenario {
 43	  name: string;
 44	  operation: McpFnInspectorOperation;
 45	  expect: unknown;
 46	}
 47	
 48	/** Headless inspector; graphical shells and the CLI consume this same engine. */
 49	export class McpFnInspector {
 50	  private readonly events: McpFnDiagnosticEvent[] = [];
 51	  private readonly unsubscribe: () => void;
 52	
 53	  constructor(readonly client: McpFnClient) {
 54	    this.unsubscribe = client.onDiagnostic((event) => {
 55	      this.events.push(redactOAuthValue(event) as McpFnDiagnosticEvent);
 56	    });
 57	  }
 58	
 59	  static create(options: McpFnClientOptions): McpFnInspector {
 60	    return new McpFnInspector(new McpFnClient(options));
 61	  }
 62	
 63	  async connect(): Promise<this> {
 64	    await this.client.connect();
 65	    return this;
 66	  }
 67	
 68	  async snapshot(): Promise<McpFnInspectorSnapshot> {
 69	    const capabilities = this.client.getServerCapabilities();
 70	    const [tools, resources, resourceTemplates, prompts] = await Promise.all([
 71	      capabilities?.tools ? this.client.tools.listAll() : Promise.resolve([]),
 72	      capabilities?.resources ? this.client.resources.listAll() : Promise.resolve([]),
 73	      capabilities?.resources ? this.client.resources.listTemplatesAll() : Promise.resolve([]),
 74	      capabilities?.prompts ? this.client.prompts.listAll() : Promise.resolve([]),
 75	    ]);
 76	    return redactOAuthValue({
 77	      target: this.client.getTargetDescriptor(),
 78	      state: this.client.state,
 79	      server: this.client.getServerVersion(),
 80	      capabilities,
 81	      tools,
 82	      resources,
 83	      resourceTemplates,
 84	      prompts,
 85	      timeline: [...this.events],
 86	    }) as McpFnInspectorSnapshot;
 87	  }
 88	
 89	  async run(operation: McpFnInspectorOperation): Promise<McpFnInspectorOperationResult> {
 90	    if (operation.kind === "tools.call") {
 91	      return this.client.tools.call(operation.name, operation.arguments);
 92	    }
 93	    if (operation.kind === "resources.read") {
 94	      return this.client.resources.read(operation.uri);
 95	    }
 96	    return this.client.prompts.get(operation.name, operation.arguments);
 97	  }
 98	
 99	  exportScenario(
100	    name: string,
101	    operation: McpFnInspectorOperation,
102	    result: McpFnInspectorOperationResult,
103	  ): McpFnExportedScenario {
104	    const redacted = redactOAuthValue({ name, operation, expect: result });
105	    return replaceSecretMarkers(redacted) as McpFnExportedScenario;
106	  }
107	
108	  timeline(): McpFnDiagnosticEvent[] {
109	    return [...this.events];
110	  }
111	
112	  async close(): Promise<void> {
113	    this.unsubscribe();
114	    await this.client.close();
115	  }
116	}
117	
118	function replaceSecretMarkers(value: unknown): unknown {
119	  if (value === "[REDACTED]") return "${MCPFN_SECRET}";
120	  if (Array.isArray(value)) return value.map(replaceSecretMarkers);
121	  if (value && typeof value === "object") {
122	    return Object.fromEntries(
123	      Object.entries(value as Record<string, unknown>)
124	        .map(([key, entry]) => [key, replaceSecretMarkers(entry)]),
125	    );
126	  }
127	  return value;
128	}

