103	export function parseBearerChallenge(
104	  header: string | null,
105	): McpFnBearerChallenge | undefined {
106	  if (!header) return undefined;
107	  const matches = [...header.matchAll(/(?:^|,)\s*([A-Za-z][A-Za-z0-9_-]*)\s+/g)];
108	  const selectedIndex = matches.findIndex((entry) => entry[1].toLowerCase() === "bearer");
109	  if (selectedIndex < 0) return undefined;
110	  const match = matches[selectedIndex];
111	  const start = (match.index ?? 0) + match[0].length;
112	  const end = matches[selectedIndex + 1]?.index ?? header.length;
113	  const parameters: Record<string, string> = {};
114	  const source = header.slice(start, end);
115	  const pattern = /([A-Za-z][A-Za-z0-9_-]*)\s*=\s*(?:"((?:[^"\\]|\\.)*)"|([^,\s]+))/g;
116	  for (const entry of source.matchAll(pattern)) {
117	    const quoted = entry[2]?.replace(/\\(["\\])/g, "$1");
118	    parameters[entry[1]] = quoted ?? entry[3] ?? "";
119	  }
120	  return { scheme: match[1], parameters };
121	}
