166	): McpFnAuthCredential {
167	  const headerName = options.headerName ?? "authorization";
168	  const value = options.scheme === ""
169	    ? apiKey
170	    : `${options.scheme ?? "Bearer"} ${apiKey}`;
171	  return { kind: "api-key", headers: { [headerName]: value } };
172	}
