  1	import Ajv from "ajv";
  2	import addFormats from "ajv-formats";
  3	import { UriTemplate } from "@modelcontextprotocol/sdk/shared/uriTemplate.js";
  4	import { ServerCapabilitiesSchema } from "@modelcontextprotocol/sdk/types.js";
  5	
  6	import { compareCodeUnits, sha256 } from "./canonical.js";
  7	import { assertMcpAppContracts } from "./apps.js";
  8	import { McpFnValidationError } from "./errors.js";
  9	import {
 10	  unsupportedUriTemplateOperator,
 11	  uriTemplatesOverlap,
 12	} from "./uri-template.js";
 13	import {
 14	  assertPromptSchemaSupportsStringValues,
 15	  promptArguments,
 16	  schemaPromptArguments,
 17	  type McpFnRegistry,
 18	} from "./registry.js";
 19	import type {
 20	  McpFnManifest,
 21	  McpFnManifestPrompt,
 22	  McpFnManifestResource,
 23	  McpFnManifestResourceTemplate,
 24	  McpFnManifestTool,
 25	  McpFnServerInfo,
 26	} from "./types.js";
 27	import type { ServerCapabilities } from "@modelcontextprotocol/sdk/types.js";
 28	
 29	export interface CreateManifestOptions {
 30	  protocolVersions?: string[];
 31	  transports?: Array<"stdio" | "streamable-http">;
 32	  capabilities?: ServerCapabilities;
 33	  clientRequirements?: McpFnManifest["clientRequirements"];
 34	  extensions?: Record<string, unknown>;
 35	}
 36	
 37	function assertSortedUnique(label: string, values: string[]): void {
 38	  const canonical = [...new Set(values)].sort(compareCodeUnits);
 39	  if (
 40	    canonical.length !== values.length ||
 41	    canonical.some((value, index) => value !== values[index])
 42	  ) throw new McpFnValidationError(`${label} must be sorted and unique`);
 43	}
 44	
 45	function assertObject(label: string, value: unknown): void {
 46	  if (!value || typeof value !== "object" || Array.isArray(value)) {
 47	    throw new McpFnValidationError(`${label} must be an object`);
 48	  }
 49	}
 50	
 51	function assertName(label: string, name: unknown): asserts name is string {
 52	  if (typeof name !== "string" || !/^[A-Za-z0-9_.-]{1,128}$/.test(name)) {
 53	    throw new McpFnValidationError(`${label} requires a name (letters, digits, dot, dash, or underscore)`);
 54	  }
 55	}
 56	
 57	function assertMetadata(label: string, value: unknown): void {
 58	  if (value !== undefined) assertObject(label, value);
 59	}
 60	
 61	function assertSortedBy<T>(label: string, values: T[], select: (value: T) => string): void {
 62	  assertSortedUnique(label, values.map(select));
 63	}
 64	
 65	export function createManifest<TContext>(
 66	  info: McpFnServerInfo,
 67	  registry: McpFnRegistry<TContext>,
 68	  options: CreateManifestOptions = {},
 69	): McpFnManifest {
 70	  assertMcpAppContracts(registry);
 71	  const tools: McpFnManifestTool[] = registry.definitions().map((tool) => ({
 72	    name: tool.name,
 73	    ...(tool.title ? { title: tool.title } : {}),
 74	    description: tool.description,
 75	    inputSchema: tool.inputSchema,
 76	    ...(tool.outputSchema ? { outputSchema: tool.outputSchema } : {}),
 77	    ...(tool.annotations ? { annotations: tool.annotations } : {}),
 78	    ...(tool.execution ? { execution: tool.execution } : {}),
 79	    ...(tool.icons ? { icons: tool.icons } : {}),
 80	    ...(tool.metadata ? { metadata: tool.metadata } : {}),
 81	  }));
 82	  const resources: McpFnManifestResource[] = registry.resourceDefinitions().map((resource) => ({
 83	    uri: resource.uri,
 84	    name: resource.name,
 85	    ...(resource.title ? { title: resource.title } : {}),
 86	    ...(resource.description ? { description: resource.description } : {}),
 87	    ...(resource.mimeType ? { mimeType: resource.mimeType } : {}),
 88	    ...(resource.annotations ? { annotations: resource.annotations } : {}),
 89	    ...(resource.icons ? { icons: resource.icons } : {}),
 90	    ...(resource.subscribe ? { subscribable: true } : {}),
 91	    ...(resource.metadata ? { metadata: resource.metadata } : {}),
 92	  }));
 93	  const resourceTemplates: McpFnManifestResourceTemplate[] =
 94	    registry.resourceTemplateDefinitions().map((resource) => ({
 95	      uriTemplate: resource.uriTemplate,
 96	      name: resource.name,
 97	      ...(resource.title ? { title: resource.title } : {}),
 98	      ...(resource.description ? { description: resource.description } : {}),
 99	      ...(resource.mimeType ? { mimeType: resource.mimeType } : {}),
100	      ...(resource.annotations ? { annotations: resource.annotations } : {}),
101	      ...(resource.icons ? { icons: resource.icons } : {}),
102	      ...(resource.subscribe ? { subscribable: true } : {}),
103	      ...(resource.metadata ? { metadata: resource.metadata } : {}),
104	    }));
105	  const prompts: McpFnManifestPrompt[] = registry.promptDefinitions().map((prompt) => ({
106	    name: prompt.name,
107	    ...(prompt.title ? { title: prompt.title } : {}),
108	    ...(prompt.description ? { description: prompt.description } : {}),
109	    ...(promptArguments(prompt) ? { arguments: promptArguments(prompt) } : {}),
110	    ...(prompt.argumentsSchema ? { argumentsSchema: prompt.argumentsSchema } : {}),
111	    ...(prompt.icons ? { icons: prompt.icons } : {}),
112	    ...(prompt.metadata ? { metadata: prompt.metadata } : {}),
113	  }));
114	  const body = {
115	    formatVersion: 1 as const,
116	    server: {
117	      name: info.name,
118	      version: info.version,
119	      ...(info.instructions ? { instructions: info.instructions } : {}),
120	    },
121	    ...(options.protocolVersions
122	      ? { protocolVersions: [...new Set(options.protocolVersions)].sort() }
123	      : {}),
124	    ...(options.transports
125	      ? { transports: [...new Set(options.transports)].sort() as Array<"stdio" | "streamable-http"> }
126	      : {}),
127	    capabilities: options.capabilities ?? registry.capabilities(),
128	    ...(options.clientRequirements
129	      ? {
130	          clientRequirements: {
131	            ...options.clientRequirements,
132	            ...(options.clientRequirements.elicitation
133	              ? { elicitation: [...new Set(options.clientRequirements.elicitation)].sort() }
134	              : {}),
135	          },
136	        }
137	      : {}),
138	    ...(options.extensions ? { extensions: options.extensions } : {}),
139	    tools,
140	    resources,
141	    resourceTemplates,
142	    prompts,
143	  };
144	  return { ...body, hash: sha256(body) };
145	}
146	
147	export function validateManifest(value: unknown): McpFnManifest {
148	  assertObject("McpFn manifest", value);
149	  const manifest = value as Partial<McpFnManifest>;
150	  if (manifest.formatVersion !== 1) {
151	    throw new McpFnValidationError("Unsupported McpFn manifest formatVersion");
152	  }
153	  if (
154	    !manifest.server || typeof manifest.server.name !== "string" || !manifest.server.name.trim() ||
155	    typeof manifest.server.version !== "string" || !manifest.server.version.trim()
156	  ) throw new McpFnValidationError("Manifest server name and version are required");
157	  if (
158	    manifest.server.instructions !== undefined &&
159	    typeof manifest.server.instructions !== "string"
160	  ) throw new McpFnValidationError("Manifest server instructions must be a string");
161	  if (!Array.isArray(manifest.tools)) {
162	    throw new McpFnValidationError("Manifest tools must be an array");
163	  }
164	  for (const [label, entries] of [
165	    ["resources", manifest.resources],
166	    ["resourceTemplates", manifest.resourceTemplates],
167	    ["prompts", manifest.prompts],
168	  ] as const) {
169	    if (entries !== undefined && !Array.isArray(entries)) {
170	      throw new McpFnValidationError(`Manifest ${label} must be an array`);
171	    }
172	  }
173	  if (
174	    manifest.protocolVersions !== undefined &&
175	    (!Array.isArray(manifest.protocolVersions) ||
176	      manifest.protocolVersions.some((version) => typeof version !== "string" || !version))
177	  ) throw new McpFnValidationError("Manifest protocolVersions must contain non-empty strings");
178	  if (manifest.protocolVersions) assertSortedUnique("Manifest protocolVersions", manifest.protocolVersions);
179	  if (
180	    manifest.transports !== undefined &&
181	    (!Array.isArray(manifest.transports) ||
182	      manifest.transports.some((transport) => transport !== "stdio" && transport !== "streamable-http"))
183	  ) throw new McpFnValidationError("Manifest contains an unsupported transport");
184	  if (manifest.transports) assertSortedUnique("Manifest transports", manifest.transports);
185	  if (manifest.capabilities !== undefined) {
186	    const parsed = ServerCapabilitiesSchema.safeParse(manifest.capabilities);
187	    if (!parsed.success) throw new McpFnValidationError("Manifest capabilities are invalid");
188	  }
189	  if (manifest.clientRequirements !== undefined) {
190	    assertObject("Manifest clientRequirements", manifest.clientRequirements);
191	    if (
192	      manifest.clientRequirements.sampling !== undefined &&
193	      typeof manifest.clientRequirements.sampling !== "boolean"
194	    ) throw new McpFnValidationError("Manifest sampling requirement must be a boolean");
195	    if (
196	      manifest.clientRequirements.roots !== undefined &&
197	      typeof manifest.clientRequirements.roots !== "boolean"
198	    ) throw new McpFnValidationError("Manifest roots requirement must be a boolean");
199	    if (
200	      manifest.clientRequirements.elicitation !== undefined &&
201	      (!Array.isArray(manifest.clientRequirements.elicitation) ||
202	        manifest.clientRequirements.elicitation.some((mode) => mode !== "form" && mode !== "url"))
203	    ) throw new McpFnValidationError("Manifest elicitation requirements are invalid");
204	    if (manifest.clientRequirements.elicitation) {
205	      assertSortedUnique(
206	        "Manifest elicitation requirements",
207	        manifest.clientRequirements.elicitation,
208	      );
209	    }
210	  }
211	  assertMetadata("Manifest extensions", manifest.extensions);
212	
213	  const ajv = new Ajv({ allErrors: true, strict: false, allowUnionTypes: true });
214	  addFormats(ajv as never);
215	  for (const tool of manifest.tools) {
216	    assertObject("Every manifest tool", tool);
217	    assertName("Every manifest tool", tool.name);
218	    if (typeof tool.description !== "string" || !tool.description.trim()) {
219	      throw new McpFnValidationError(`Manifest tool ${tool.name} requires a description`);
220	    }

