  | { kind: "tools.call"; name: string; arguments?: Record<string, unknown> }
  | { kind: "resources.read"; uri: string }
  | { kind: "prompts.get"; name: string; arguments?: Record<string, string> };

export type McpFnInspectorOperationResult =
  | CallToolResult
  | ReadResourceResult
  | GetPromptResult;

export interface McpFnExportedScenario {
  name: string;
  operation: McpFnInspectorOperation;
  expect: unknown;
}

/** Headless inspector; graphical shells and the CLI consume this same engine. */
export class McpFnInspector {
  private readonly events: McpFnDiagnosticEvent[] = [];
  private readonly unsubscribe: () => void;

  constructor(readonly client: McpFnClient) {
    this.unsubscribe = client.onDiagnostic((event) => {
      this.events.push(redactOAuthValue(event) as McpFnDiagnosticEvent);
    });
  }

  static create(options: McpFnClientOptions): McpFnInspector {
    return new McpFnInspector(new McpFnClient(options));
  }

  async connect(): Promise<this> {
    await this.client.connect();
    return this;
  }

  async snapshot(): Promise<McpFnInspectorSnapshot> {
    const capabilities = this.client.getServerCapabilities();
    const [tools, resources, resourceTemplates, prompts] = await Promise.all([
      capabilities?.tools ? this.client.tools.listAll() : Promise.resolve([]),
      capabilities?.resources ? this.client.resources.listAll() : Promise.resolve([]),
      capabilities?.resources ? this.client.resources.listTemplatesAll() : Promise.resolve([]),
      capabilities?.prompts ? this.client.prompts.listAll() : Promise.resolve([]),
    ]);
    return redactOAuthValue({
      target: this.client.getTargetDescriptor(),
      state: this.client.state,
      server: this.client.getServerVersion(),
      capabilities,
      tools,
      resources,
      resourceTemplates,
      prompts,
      timeline: [...this.events],
    }) as McpFnInspectorSnapshot;
  }

  async run(operation: McpFnInspectorOperation): Promise<McpFnInspectorOperationResult> {
    if (operation.kind === "tools.call") {
      return this.client.tools.call(operation.name, operation.arguments);
    }
    if (operation.kind === "resources.read") {
      return this.client.resources.read(operation.uri);
    }
    return this.client.prompts.get(operation.name, operation.arguments);
  }

  exportScenario(
    name: string,
    operation: McpFnInspectorOperation,
    result: McpFnInspectorOperationResult,
  ): McpFnExportedScenario {
    const redacted = redactOAuthValue({ name, operation, expect: result });
    return replaceSecretMarkers(redacted) as McpFnExportedScenario;
  }

  timeline(): McpFnDiagnosticEvent[] {
    return [...this.events];
  }

  async close(): Promise<void> {
    this.unsubscribe();
    await this.client.close();
  }
}

function replaceSecretMarkers(value: unknown): unknown {
  if (value === "[REDACTED]") return "${MCPFN_SECRET}";
  if (Array.isArray(value)) return value.map(replaceSecretMarkers);
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .map(([key, entry]) => [key, replaceSecretMarkers(entry)]),
    );
  }
  return value;
}
import type { CallToolResult } from "@modelcontextprotocol/sdk/types.js";

import { McpFnAssertionError, assertStructuredTextParity, stableJson } from "./assertions.js";
import type { McpFnTestClient } from "./client.js";

export interface McpFnToolScenario {
  name: string;
  kind?: "tools.call";
  tool: string;
  arguments?: Record<string, unknown>;
  expect?: {
    isError?: boolean;
    structuredContent?: unknown;
    structuredTextParity?: boolean;
  };
  verify?(result: CallToolResult): void | Promise<void>;
}

export interface McpFnInventoryScenario {
  name: string;
  kind: "tools.list" | "resources.list" | "resources.templates.list" | "prompts.list";
  expectNames?: string[];
}

export interface McpFnResourceScenario {
  name: string;
  kind: "resources.read" | "resources.subscribe" | "resources.unsubscribe";
  uri: string;
  expect?: unknown;
}

export interface McpFnPromptScenario {
  name: string;
  kind: "prompts.get";
  prompt: string;
  arguments?: Record<string, string>;
  expect?: unknown;
}

export interface McpFnInitializeScenario {
  name: string;
  kind: "initialize";
  expectCapabilities?: Record<string, unknown>;
}

export type McpFnScenario =
  | McpFnToolScenario
  | McpFnInventoryScenario
  | McpFnResourceScenario
  | McpFnPromptScenario
  | McpFnInitializeScenario;

export interface McpFnScenarioResult {
  name: string;
  operation: string;
  tool?: string;
  status: "passed" | "failed";
  durationMs: number;
  error?: string;
}

export async function runScenarios(
  client: McpFnTestClient<unknown>,
  scenarios: McpFnScenario[],
): Promise<McpFnScenarioResult[]> {
  const results: McpFnScenarioResult[] = [];
  for (const scenario of scenarios) {
    const startedAt = performance.now();
    const operation = scenario.kind ?? "tools.call";
    try {
      await executeScenario(client, scenario);
      results.push({
        name: scenario.name,
        operation,
        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
        status: "passed",
        durationMs: performance.now() - startedAt,
      });
    } catch (error) {
      results.push({
        name: scenario.name,
        operation,
        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
        status: "failed",
        durationMs: performance.now() - startedAt,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }
  return results;
}

async function executeScenario(
  client: McpFnTestClient<unknown>,
  scenario: McpFnScenario,
): Promise<void> {
  const kind = scenario.kind ?? "tools.call";
  if (kind === "tools.call" && isToolScenario(scenario)) {
    const result = await client.callTool(scenario.tool, scenario.arguments);
    if (result.isError && scenario.expect?.isError === undefined) {
      throw new McpFnAssertionError(
        "Tool returned isError=true without an explicit expect.isError=true assertion",
      );
    }
    if (
      scenario.expect?.isError !== undefined &&
      Boolean(result.isError) !== scenario.expect.isError
    ) {
      throw new McpFnAssertionError(
        `Expected isError=${scenario.expect.isError}, received ${Boolean(result.isError)}`,
      );
    }
    if (
      scenario.expect &&
      Object.prototype.hasOwnProperty.call(scenario.expect, "structuredContent") &&
      stableJson(result.structuredContent) !== stableJson(scenario.expect.structuredContent)
    ) {
      throw new McpFnAssertionError(
        `Structured result mismatch\nexpected: ${stableJson(scenario.expect.structuredContent)}\nactual:   ${stableJson(result.structuredContent)}`,
      );
    }
    if (scenario.expect?.structuredTextParity) assertStructuredTextParity(result);
    await scenario.verify?.(result);
    return;
  }
  if (kind === "initialize" && scenario.kind === "initialize") {
    const actual = client.client.getServerCapabilities() ?? {};
    if (scenario.expectCapabilities && stableJson(actual) !== stableJson(scenario.expectCapabilities)) {
      throw new McpFnAssertionError(
        `Capability mismatch\nexpected: ${stableJson(scenario.expectCapabilities)}\nactual:   ${stableJson(actual)}`,
      );
    }
    return;
  }
  if (isInventoryScenario(scenario)) {
    const values = kind === "tools.list"
      ? await client.listTools()
      : kind === "resources.list"
        ? await client.listResources()
        : kind === "resources.templates.list"
          ? await client.listResourceTemplates()
          : await client.listPrompts();
    if (scenario.expectNames) {
      const actual = values.map((value) => value.name).sort();
      const expected = [...scenario.expectNames].sort();
      if (stableJson(actual) !== stableJson(expected)) {
        throw new McpFnAssertionError(
          `Inventory mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
        );
      }
    }
    return;
  }
  if (scenario.kind === "resources.read") {
    assertExpected(await client.readResource(scenario.uri), scenario.expect);
    return;
  }
  if (scenario.kind === "resources.subscribe") {
    await client.subscribeResource(scenario.uri);
    return;
  }
  if (scenario.kind === "resources.unsubscribe") {
    await client.unsubscribeResource(scenario.uri);
    return;
  }
  if (scenario.kind === "prompts.get") {
    assertExpected(
      await client.getPrompt(scenario.prompt, scenario.arguments),
      scenario.expect,
    );
    return;
  }
  throw new McpFnAssertionError(`Unsupported scenario operation ${kind}`);
}

function assertExpected(actual: unknown, expected: unknown): void {
  if (expected !== undefined && stableJson(actual) !== stableJson(expected)) {
    throw new McpFnAssertionError(
      `Scenario result mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
    );
  }
}

function isToolScenario(scenario: McpFnScenario): scenario is McpFnToolScenario {
  return "tool" in scenario;
}

function isInventoryScenario(scenario: McpFnScenario): scenario is McpFnInventoryScenario {
  return ["tools.list", "resources.list", "resources.templates.list", "prompts.list"]
    .includes(scenario.kind ?? "");
}
import type { Implementation, ServerCapabilities } from "@modelcontextprotocol/sdk/types.js";
import type { McpFnTarget, McpFnTargetDescriptor } from "@mcpfn/client";
import type { McpFnManifest } from "@mcpfn/core";

import { assertManifestContract } from "./assertions.js";
import { McpFnTestClient, type McpFnTestClientOptions } from "./client.js";
import {
  runScenarios,
  type McpFnScenario,
  type McpFnScenarioResult,
} from "./scenarios.js";

export interface RunMcpFnTargetSuiteOptions {
  target: McpFnTarget;
  scenarios?: McpFnScenario[];
  manifest?: McpFnManifest;
  expectedToolNames?: readonly string[];
  clientInfo?: Implementation;
  client?: McpFnTestClientOptions;
}

export interface McpFnTargetSuiteReport {
  ok: boolean;
  target: McpFnTargetDescriptor;
  server?: Implementation;
  capabilities?: ServerCapabilities;
  manifestChecked: boolean;
  total: number;
  passed: number;
  failed: number;
  results: McpFnScenarioResult[];
}

/** Runs local, stdio, HTTP, or custom targets through the production session engine. */
export async function runMcpFnTargetSuite(
  options: RunMcpFnTargetSuiteOptions,
): Promise<McpFnTargetSuiteReport> {
  const client = await McpFnTestClient.connectTarget(
    options.target,
    options.clientInfo ?? { name: "mcpfn-suite", version: "0.0.1" },
    options.client,
  );
  try {
    if (options.manifest) {
      await assertManifestContract(client, options.manifest, {
        expectedToolNames: options.expectedToolNames,
      });
    }
    const results = await runScenarios(client, options.scenarios ?? []);
    const failed = results.filter((result) => result.status === "failed").length;
    return {
      ok: failed === 0,
      target: options.target.describe(),
      server: client.session.getServerVersion(),
      capabilities: client.session.getServerCapabilities(),
      manifestChecked: Boolean(options.manifest),
      total: results.length,
      passed: results.length - failed,
      failed,
      results,
    };
  } finally {
    await client.close();
  }
}

