 17	async function loadReleaseTargets() {
 18	  const raw = await readFile(releasePackagesPath, 'utf8');
 19	  const releasePackages = JSON.parse(raw);
 20	
 21	  if (!Array.isArray(releasePackages)) {
 22	    fail(`Expected ${path.relative(repoRoot, releasePackagesPath)} to contain an array`);
 23	  }
 24	
 25	  const targets = [];
 26	
 27	  for (const entry of releasePackages) {
 28	    if (!entry?.slug || !entry?.path || !entry?.name) {
 29	      fail(`Invalid release target entry in ${path.relative(repoRoot, releasePackagesPath)}: ${JSON.stringify(entry)}`);
 30	    }
 31	
 32	    const packageJsonFile = path.join(repoRoot, entry.path, 'package.json');
 33	    const packageJson = JSON.parse(await readFile(packageJsonFile, 'utf8'));
 34	
 35	    if (packageJson.name !== entry.name) {
 36	      fail(
 37	        `Release target ${entry.slug} expected ${entry.name} at ${entry.path}/package.json, found ${packageJson.name ?? 'undefined'}`,
 38	      );
 39	    }
 40	
 41	    targets.push({
 42	      slug: entry.slug,
 43	      name: entry.name,
 44	      version: packageJson.version,
 45	      path: entry.path,
 46	    });
