 37	export function createMcpFnAuthProviderAdapter<TSession extends AuthSession>(
 38	  options: McpFnAuthProviderAdapterOptions<TSession>,
 39	): McpFnAuthProviderAdapter<TSession> {
 40	  const resource = new URL(options.resource.toString());
 41	  resource.hash = "";
 42	  return {
 43	    async authenticate(request) {
 44	      const session = await options.provider.authenticate(request);
 45	      if (!session) return null;
 46	      const principal = options.map
 47	        ? await options.map(session, request)
 48	        : defaultPrincipal(session);
 49	      if (options.authorize && !(await options.authorize({ principal, request }))) {
 50	        return null;
 51	      }
 52	      const bearer = /^Bearer\s+(.+)$/i.exec(
 53	        request.headers.get("authorization")?.trim() ?? "",
 54	      )?.[1] ?? "";
 55	      return {
 56	        session,
 57	        principal,
 58	        authInfo: {
 59	          token: bearer,
 60	          clientId: principal.clientId,
 61	          scopes: [...principal.scopes],
 62	          ...(principal.expiresAt ? { expiresAt: principal.expiresAt } : {}),
 63	          resource,
 64	          extra: {
 65	            subject: principal.subject,
 66	            resourceIds: [...principal.resourceIds],
 67	            ...(principal.tenantId ? { tenantId: principal.tenantId } : {}),
 68	            ...(principal.regionId ? { regionId: principal.regionId } : {}),
 69	            ...(principal.authMethods ? { authMethods: [...principal.authMethods] } : {}),
 70	            ...principal.extra,
 71	          },
 72	        },
 73	      };
 74	    },
 75	  };
 76	}
