179	  private async connectInternal(): Promise<void> {
180	    const retries = this.options.connectRetries ?? 0;
181	    let lastError: unknown;
182	    for (let attempt = 0; attempt <= retries; attempt += 1) {
183	      const requestId = this.requestId();
184	      this._state = "connecting";
185	      await this.emit("transport-connect", "started", requestId, undefined, { attempt });
186	      try {
