191	      } catch (error) {
192	        lastError = error;
193	        await this.emit("transport-connect", "failed", requestId, "MCPFN_TARGET_OPEN_FAILED", {
194	          attempt,
195	          message: errorMessage(error),
196	        });
197	        if (attempt < retries) {
198	          await delay(this.options.connectRetryDelayMs ?? 100);
199	          continue;
200	        }
201	        this._state = "idle";
