179	  private async connectInternal(): Promise<void> {
180	    const retries = this.options.connectRetries ?? 0;
181	    let lastError: unknown;
182	    for (let attempt = 0; attempt <= retries; attempt += 1) {
183	      const requestId = this.requestId();
184	      this._state = "connecting";
185	      await this.emit("transport-connect", "started", requestId, undefined, { attempt });
186	      try {
187	        this.handle = await this.options.target.open({
188	          requestId,
189	          diagnostic: (event) => this.dispatch(event),
190	        });
191	      } catch (error) {
192	        lastError = error;
193	        await this.emit("transport-connect", "failed", requestId, "MCPFN_TARGET_OPEN_FAILED", {
194	          attempt,
195	          message: errorMessage(error),
196	        });
197	        if (attempt < retries) {
198	          await delay(this.options.connectRetryDelayMs ?? 100);
199	          continue;
200	        }
201	        this._state = "idle";
202	        throw new McpFnClientError(
203	          "MCPFN_TARGET_OPEN_FAILED",
204	          "Failed to open the MCP target",
205	          { phase: "transport-connect", retryable: true, cause: error },
206	        );
207	      }
208	
209	      const protocol = new Client(
210	        this.options.info ?? { name: "mcpfn-client", version: "0.0.1" },
211	        {
212	          ...this.options.clientOptions,
213	          capabilities: this.options.capabilities ?? {},
214	        },
215	      );
216	      this._protocol = protocol;
217	      protocol.onerror = (error) => {
218	        void this.emit("capability-operation", "failed", this.requestId(), errorCode(error), {
219	          message: error.message,
220	          source: "protocol",
221	        });
222	      };
223	      protocol.onclose = () => {
224	        if (this._state === "connected") this._state = "idle";
225	        void this.emit("transport-close", "succeeded", this.requestId());
226	      };
227	      await this.options.configure?.(protocol);
228	      await this.emit("mcp-initialize", "started", requestId);
229	      try {
230	        await protocol.connect(this.handle.transport);
231	        this._state = "connected";
232	        await this.emit("transport-connect", "succeeded", requestId, undefined, { attempt });
233	        await this.emit("mcp-initialize", "succeeded", requestId, undefined, {
234	          server: protocol.getServerVersion(),
235	          capabilities: protocol.getServerCapabilities(),
236	        });
