 81	        name: scenario.name,
 82	        operation,
 83	        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
 84	        status: "failed",
 85	        durationMs: performance.now() - startedAt,
 86	        error: error instanceof Error ? error.message : String(error),
 87	      });
 88	    }
 89	  }
 90	  return results;
 91	}
