 45	export function createOAuthAuthorizationRequestUrl(
 46	  options: McpFnOAuthAuthorizationRequestOptions,
 47	): { url: string; pkce: McpFnPkcePair; state: string } {
 48	  const pkce = options.pkce ?? createPkcePair();
 49	  const state = options.state ?? `mcpfn_state_${randomUUID()}`;
 50	  const url = new URL(options.authorizationEndpoint);
 51	  for (const [name, value] of Object.entries(options.extraParameters ?? {})) {
 52	    url.searchParams.set(name, value);
 53	  }
 54	  url.searchParams.set("response_type", "code");
 55	  url.searchParams.set("client_id", options.clientId);
 56	  url.searchParams.set("redirect_uri", options.redirectUri);
 57	  url.searchParams.set("code_challenge", pkce.challenge);
 58	  url.searchParams.set("code_challenge_method", pkce.method);
 59	  url.searchParams.set("state", state);
 60	  if (options.scopes?.length) url.searchParams.set("scope", options.scopes.join(" "));
 61	  if (options.resource) url.searchParams.set("resource", options.resource);
 62	  return { url: url.toString(), pkce, state };
 63	}
