 65	export function parseOAuthCallback(url: string | URL): McpFnOAuthCallback {
 66	  const callback = new URL(url);
 67	  return {
 68	    url: callback.toString(),
 69	    parameters: Object.fromEntries(callback.searchParams),
 70	  };
 71	}
