 73	/** Drives an authorization-code + PKCE approval or denial through real UI. */
 74	export async function authorizeWithBrowser(
 75	  page: Page,
 76	  options: McpFnOAuthBrowserOptions,
 77	): Promise<McpFnOAuthBrowserResult> {
 78	  const request = createOAuthAuthorizationRequestUrl(options);
 79	  await page.goto(request.url);
 80	  await options.beforeDecision?.(page);
 81	  const decision = options.decision ?? "approve";
 82	  const buttonName = decision === "approve"
 83	    ? options.approveButtonName ?? /^approve$/i
 84	    : options.denyButtonName ?? /^deny$/i;
 85	  await page.getByRole("button", { name: buttonName }).click();
 86	  const redirect = new URL(options.redirectUri);
 87	  await page.waitForURL((candidate) =>
 88	    candidate.origin === redirect.origin && candidate.pathname === redirect.pathname);
 89	  const callback = parseOAuthCallback(page.url());
 90	  if (callback.parameters.state !== request.state) {
 91	    throw new Error("OAuth callback state does not match the authorization request");
 92	  }
 93	  return {
 94	    authorizationUrl: request.url,
 95	    callback,
 96	    pkce: request.pkce,
 97	    state: request.state,
 98	  };
 99	}
