 99	export function validateMcpAuthorizationRequest(options: {
100	  url: string | URL;
101	  client: McpFnNormalizedClientRegistration;
102	  redirectPolicy?: McpFnRedirectPolicy;
103	  allowedResources?: ReadonlyArray<string | URL>;
104	  supportedScopes?: ReadonlyArray<string>;
105	}): McpFnValidatedAuthorizationRequest {
106	  const url = new URL(options.url.toString());
107	  const responseType = url.searchParams.get("response_type");
108	  if (responseType !== "code" || !options.client.responseTypes.includes("code")) {
109	    throw new McpFnHostedAuthorizationError(
110	      "unsupported_response_type",
111	      "This MCP authorization profile requires response_type=code",
112	    );
113	  }
114	  if (!options.client.grantTypes.includes("authorization_code")) {
115	    throw new McpFnHostedAuthorizationError(
116	      "unauthorized_client",
117	      "The client has no compatible authorization_code flow",
118	    );
119	  }
120	  const requestedClientId = url.searchParams.get("client_id");
121	  if (requestedClientId !== options.client.clientId) {
122	    throw new McpFnHostedAuthorizationError("invalid_client", "client_id does not match registration");
123	  }
124	  const redirectUri = url.searchParams.get("redirect_uri");
125	  if (!redirectUri) {
126	    throw new McpFnHostedAuthorizationError("invalid_request", "redirect_uri is required");
127	  }
128	  let redirectMatch;
129	  try {
130	    redirectMatch = matchMcpRedirectUri(
131	      redirectUri,
132	      options.client.redirectUris,
133	      options.redirectPolicy,
134	    );
135	  } catch (error) {
136	    if (error instanceof McpFnRedirectMismatchError) {
137	      throw new McpFnHostedAuthorizationError(
138	        "invalid_request",
139	        error.message,
140	        { details: { phase: "redirect-validation", redirect: error.requested } },
141	      );
142	    }
143	    throw error;
144	  }
145	  const codeChallenge = url.searchParams.get("code_challenge");
146	  if (!codeChallenge) {
147	    throw new McpFnHostedAuthorizationError("invalid_request", "PKCE code_challenge is required");
148	  }
149	  if (url.searchParams.get("code_challenge_method") !== "S256") {
150	    throw new McpFnHostedAuthorizationError(
151	      "invalid_request",
152	      "PKCE code_challenge_method must be S256",
153	    );
154	  }
155	  const resource = url.searchParams.get("resource") ?? undefined;
156	  if (resource && options.allowedResources?.length) {
157	    const allowed = new Set(options.allowedResources.map((value) => new URL(value.toString()).toString()));
158	    if (!allowed.has(new URL(resource).toString())) {
159	      throw new McpFnHostedAuthorizationError("invalid_target", "resource is not allowed");
160	    }
161	  }
162	  const scopes = unique((url.searchParams.get("scope") ?? "").split(/\s+/).filter(Boolean));
163	  if (options.supportedScopes) {
164	    const supported = new Set(options.supportedScopes);
165	    const unsupported = scopes.filter((scope) => !supported.has(scope));
166	    if (unsupported.length) {
167	      throw new McpFnHostedAuthorizationError("invalid_scope", "Requested MCP scope is unsupported", {
168	        details: { unsupportedScopes: unsupported },
169	      });
170	    }
171	  }
172	  return {
173	    client: options.client,
174	    responseType: "code",
175	    redirectUri: new URL(redirectUri).toString(),
176	    redirectMatch: redirectMatch.kind,
177	    codeChallenge,
178	    codeChallengeMethod: "S256",
179	    scopes,
180	    ...(url.searchParams.get("state") ? { state: url.searchParams.get("state")! } : {}),
181	    ...(resource ? { resource: new URL(resource).toString() } : {}),
182	    raw: new URLSearchParams(url.searchParams),
183	  };
184	}
