 64	export function checkHostCompatibility(
 65	  manifest: McpFnManifest,
 66	  profile: McpFnHostProfile,
 67	): McpFnHostCompatibilityResult {
 68	  const issues: McpFnHostCompatibilityIssue[] = [];
 69	  if (
 70	    manifest.protocolVersions?.length &&
 71	    !manifest.protocolVersions.some((version) => profile.protocolVersions.includes(version))
 72	  ) {
 73	    issues.push({
 74	      severity: "incompatible",
 75	      code: "protocol-version-mismatch",
 76	      path: "protocolVersions",
 77	      message: `${profile.name} and ${manifest.server.name} have no protocol version in common`,
 78	    });
 79	  }
 80	
 81	  const supportedServerFeatures = new Set(profile.serverFeatures);
 82	  for (const feature of Object.keys(manifest.capabilities ?? {})) {
 83	    if (
 84	      feature === "experimental" ||
 85	      supportedServerFeatures.has(feature as McpFnServerFeature)
 86	    ) continue;
 87	    issues.push({
 88	      severity: "degraded",
 89	      code: "server-feature-unavailable",
 90	      path: `capabilities.${feature}`,
 91	      message: `${profile.name} will not expose the server's ${feature} feature`,
 92	    });
 93	  }
 94	
 95	  const required = manifest.clientRequirements;
 96	  if (required?.sampling && !profile.clientFeatures?.sampling) {
 97	    issues.push({
 98	      severity: "incompatible",
 99	      code: "sampling-required",
100	      path: "clientRequirements.sampling",
101	      message: `${manifest.server.name} requires client sampling`,
102	    });
103	  }
104	  if (required?.roots && !profile.clientFeatures?.roots) {
105	    issues.push({
106	      severity: "incompatible",
107	      code: "roots-required",
108	      path: "clientRequirements.roots",
109	      message: `${manifest.server.name} requires client roots`,
110	    });
111	  }
112	  for (const mode of required?.elicitation ?? []) {
113	    if (!profile.clientFeatures?.elicitation?.includes(mode)) {
114	      issues.push({
115	        severity: "incompatible",
116	        code: "elicitation-required",
117	        path: `clientRequirements.elicitation.${mode}`,
118	        message: `${manifest.server.name} requires ${mode} elicitation`,
119	      });
120	    }
121	  }
122	
123	  const extensions = new Set(profile.extensions ?? []);
124	  for (const [extension, configuration] of Object.entries(manifest.extensions ?? {})) {
125	    if (extensions.has(extension)) continue;
126	    const requiredExtension =
127	      configuration && typeof configuration === "object" &&
128	      (configuration as Record<string, unknown>).required === true;
129	    issues.push({
130	      severity: requiredExtension ? "incompatible" : "degraded",
131	      code: "extension-unavailable",
132	      path: `extensions.${extension}`,
133	      message: `${profile.name} does not support ${extension}`,
134	    });
135	  }
136	
137	  if (!extensions.has(MCP_APP_EXTENSION_ID)) {
138	    for (const tool of manifest.tools) {
139	      const ui = tool.metadata?.ui as { visibility?: string[] } | undefined;
140	      if (ui?.visibility?.length && !ui.visibility.includes("model")) {
141	        issues.push({
142	          severity: "incompatible",
143	          code: "app-only-tool-unavailable",
144	          path: `tools.${tool.name}.metadata.ui.visibility`,
145	          message: `${tool.name} is app-only but ${profile.name} does not support MCP Apps`,
146	        });
147	      }
148	    }
149	  }
150	
151	  issues.sort((left, right) => left.path.localeCompare(right.path) || left.code.localeCompare(right.code));
152	  const status = issues.some((issue) => issue.severity === "incompatible")
153	    ? "incompatible"
154	    : issues.length
155	      ? "degraded"
156	      : "compatible";
157	  return { status, compatible: status !== "incompatible", issues };
158	}
