 1	import {
 2	  exchangeAuthorizationCode,
 3	  expect,
 4	  refreshOAuthAccessToken,
 5	  revokeOAuthToken,
 6	  test,
 7	} from "../src/playwright.js";
 8	
 9	test("runs a browser PKCE flow for extensible client metadata", async ({
10	  page,
11	  mcpfnOAuth,
12	}) => {
13	  const clientId = mcpfnOAuth.server.clientMetadataUrl("jwtBearerExtension");
14	  const authorization = await mcpfnOAuth.authorize(page, {
15	    clientId,
16	    scopes: ["mcp:read"],
17	    resource: "https://mcp.example.com/mcp",
18	  });
19	  const code = authorization.callback.parameters.code;
20	  expect(code).toBeTruthy();
21	
22	  const tokens = await exchangeAuthorizationCode({
23	    tokenEndpoint: mcpfnOAuth.server.tokenEndpoint,
24	    clientId,
25	    redirectUri: mcpfnOAuth.server.callbackUrl,
26	    code,
27	    codeVerifier: authorization.pkce.verifier,
28	  });
29	  const verified = await mcpfnOAuth.server.verifyAccessToken(tokens.access_token);
30	  expect(verified).toMatchObject({
31	    clientId,
32	    scopes: ["mcp:read"],
33	  });
34	  expect(verified.resource?.href).toBe("https://mcp.example.com/mcp");
35	
36	  const refreshed = await refreshOAuthAccessToken({
37	    tokenEndpoint: mcpfnOAuth.server.tokenEndpoint,
38	    clientId,
39	    refreshToken: tokens.refresh_token,
40	  });
41	  expect(refreshed.refresh_token).not.toBe(tokens.refresh_token);
42	  await expect(mcpfnOAuth.server.verifyAccessToken(refreshed.access_token)).resolves.toMatchObject({
43	    clientId,
44	  });
45	  const rotated = await refreshOAuthAccessToken({
46	    tokenEndpoint: mcpfnOAuth.server.tokenEndpoint,
47	    clientId,
48	    refreshToken: refreshed.refresh_token,
49	  });
50	  await expect(refreshOAuthAccessToken({
51	    tokenEndpoint: mcpfnOAuth.server.tokenEndpoint,
52	    clientId,
53	    refreshToken: tokens.refresh_token,
54	  })).rejects.toThrow(/Refresh token is invalid or expired/);
55	  await revokeOAuthToken({
56	    revocationEndpoint: mcpfnOAuth.server.revocationEndpoint,
57	    token: rotated.access_token,
58	  });
59	  await expect(mcpfnOAuth.server.verifyAccessToken(rotated.access_token)).rejects.toThrow(
60	    "Invalid access token",
61	  );
62	});

