  5	import type {
  6	  AuthorizationServerMetadata,
  7	  OAuthProtectedResourceMetadata,
  8	} from "@modelcontextprotocol/sdk/shared/auth.js";
  9	import { redactOAuthValue } from "@superfunctions/oauth-core";
