 11	export interface McpFnAuthorizationDiagnosticStep {
 12	  phase: "resource-discovery" | "authorization-server-discovery";
 13	  status: "passed" | "failed";
 14	  durationMs: number;
 15	  error?: string;
 16	}
 17	
 18	export interface McpFnAuthorizationDiagnosticReport {
 19	  ok: boolean;
 20	  target: string;
 21	  resourceMetadata?: OAuthProtectedResourceMetadata;
 22	  authorizationServerMetadata?: AuthorizationServerMetadata;
 23	  steps: McpFnAuthorizationDiagnosticStep[];
 24	}
 25	
 26	export interface DiagnoseMcpAuthorizationOptions {
 27	  fetchImplementation?: typeof fetch;
 28	  protocolVersion?: string;
 29	  resourceMetadataUrl?: string | URL;
 30	  timeoutMs?: number;
 31	}
 32	
 33	/** Read-only discovery probe. It does not open a browser or exchange credentials. */
 34	export async function diagnoseMcpAuthorization(
 35	  target: string | URL,
 36	  options: DiagnoseMcpAuthorizationOptions = {},
 37	): Promise<McpFnAuthorizationDiagnosticReport> {
 38	  const targetUrl = new URL(target.toString());
 39	  targetUrl.hash = "";
 40	  const steps: McpFnAuthorizationDiagnosticStep[] = [];
 41	  const fetchImplementation = boundedFetch(
 42	    options.fetchImplementation ?? globalThis.fetch,
 43	    options.timeoutMs ?? 10_000,
 44	  );
 45	  let resourceMetadata: OAuthProtectedResourceMetadata | undefined;
 46	  let authorizationServerMetadata: AuthorizationServerMetadata | undefined;
 47	
 48	  const resourceStartedAt = performance.now();
 49	  try {
 50	    resourceMetadata = await discoverOAuthProtectedResourceMetadata(
 51	      targetUrl,
 52	      {
 53	        protocolVersion: options.protocolVersion,
 54	        resourceMetadataUrl: options.resourceMetadataUrl,
 55	      },
 56	      fetchImplementation,
 57	    );
 58	    steps.push({
 59	      phase: "resource-discovery",
 60	      status: "passed",
 61	      durationMs: performance.now() - resourceStartedAt,
 62	    });
 63	  } catch (error) {
 64	    steps.push({
 65	      phase: "resource-discovery",
 66	      status: "failed",
 67	      durationMs: performance.now() - resourceStartedAt,
 68	      error: errorMessage(error),
 69	    });
 70	    return redactReport({ ok: false, target: targetUrl.toString(), steps });
 71	  }
 72	
 73	  const authorizationServerUrl = resourceMetadata?.authorization_servers?.[0]
 74	    ?? targetUrl.origin;
 75	  const authorizationStartedAt = performance.now();
 76	  try {
 77	    authorizationServerMetadata = await discoverAuthorizationServerMetadata(
 78	      authorizationServerUrl,
 79	      {
 80	        fetchFn: fetchImplementation,
 81	        protocolVersion: options.protocolVersion,
 82	      },
 83	    );
 84	    if (!authorizationServerMetadata) {
 85	      throw new Error("No RFC 8414 or OpenID Connect authorization metadata was found");
 86	    }
 87	    steps.push({
 88	      phase: "authorization-server-discovery",
 89	      status: "passed",
 90	      durationMs: performance.now() - authorizationStartedAt,
 91	    });
 92	  } catch (error) {
 93	    steps.push({
 94	      phase: "authorization-server-discovery",
 95	      status: "failed",
 96	      durationMs: performance.now() - authorizationStartedAt,
 97	      error: errorMessage(error),
 98	    });
 99	  }
100	
101	  return redactReport({
102	    ok: steps.every((step) => step.status === "passed"),
103	    target: targetUrl.toString(),
104	    resourceMetadata,
105	    authorizationServerMetadata,
106	    steps,
107	  });
108	}
