::code-comment{title="[P2] Export the shared scenario format" body="This nested operation object is structurally incompatible with McpFnScenario, which expects top-level kind and tool, uri, or prompt fields. Exported cases cannot be replayed by runScenarios." file="/Users/serro/Documents/dev/n/worktrees/superfunctions/MCP-2/mcpfn/inspector/src/index.ts" start=99 end=105 priority=2}
